(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-2bit-kv-long-video"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-1\">一 · 一个线上事故：KV池先于算力耗尽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-2\">二 · 它压缩的是什么：按帧、按头、按通道分组的历史KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-3\">三 · 分层bit宽度为什么必须存在：全2bit的注意力塌缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-4\">四 · 适用边界的量化判据：什么时候值得压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-5\">五 · 事故复盘落到机制：先量池，再量kernel</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-6\">六 · 边界：它救的是显存，不是所有慢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-7\">七 · 逐帧写入：分组、amax 与重要性打分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-8\">八 · 分层落池：近期窗口 FP8、历史帧降位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-9\">九 · 读出 gather：按 bit 宽度分组取数与 LUT 去量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-10\">十 · 残差补偿：相邻 FP8 帧插值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-11\">十一 · 帧级淘汰：控制池上限与误删风险</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-12\">十二 · 压缩路径的边界：从带宽受限滑向计算受限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-13\">十三 · 量化公式的逐项拆解：从 x 到 q 再到 x̂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-14\">十四 · 残差补偿项的推导：为什么是相邻帧均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-15\">十五 · 重要性打分与 bit 分配的判定式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-16\">十六 · 读出路径的伪代码：分组 gather 与 LUT 去量化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-17\">十七 · 帧淘汰与池上限的预算式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-18\">十八 · 稳定性条件与失败模式的公式化表述</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-19\">十九 · 请求形态：谁该走这条路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-20\">二十 · 长度分布：KV 池上限决定 batch 与时长</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-21\">二十一 · 并发与批大小：SLO 是首帧时延加持续吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-22\">二十二 · 负载不对时：三种可观测的退化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-23\">二十三 · 路由与回退：把配方写成判定表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-24\">二十四 · 与训练分布的耦合：打分器是配方的隐藏前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-25\">二十五 · 负载配方与失效边界：这套方案在什么请求形态下才划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-26\">二十六 · 硬件档位与KV池的物理边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-27\">二十七 · 并行拓扑：把查表去量化放在哪一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-28\">二十八 · 量化方案：分层bit宽度与打分口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-29\">二十九 · KV策略：淘汰、上限与稳定性三联</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-30\">三十 · 调度参数与可复现的配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-31\">三十一 · 边界条件：压缩收益何时被去量化开销吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-32\">三十二 · 显存账本：KV池上限先于HBM容量触顶</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-33\">三十三 · 带宽与计算的角色互换：去量化把注意力推过拐点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-34\">三十四 · 通信：分层bit宽度改变的是all-gather的字节结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-35\">三十五 · 功耗与持续吞吐：解码阶段的能效拐点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-36\">三十六 · 尾延迟：淘汰策略与池上限的耦合是抖动源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-37\">三十七 · 规模上去以后哪里先崩：三个次序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-38\">三十八 · 当压缩比撞上指令开销：2bit KV 池的崩点在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-39\">三十九 · 压缩比翻过临界点之后，先崩的是注意力 kernel 的指令流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-40\">四十 · 精度失败模式：从“注意力塌缩”到“残差补偿失效”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-41\">四十一 · 显存与OOM：KV池上限、帧级淘汰与碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-42\">四十二 · 批抖动与路由不均：连续批处理下的2bit组倾斜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-43\">四十三 · 尾延迟尖刺：淘汰、重算与去量化路径切换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-44\">四十四 · 监控体系与回滚：从指标到可执行动作</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-45\">四十五 · 失败模式与训练分布的耦合：淘汰策略的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-46\">四十六 · 失效边界：当2bit压缩把注意力kernel推向计算受限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-47\">四十七 · 对照轴：压缩率、精度分层与 kernel 形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-48\">四十八 · 决策表：五种工况下的选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-49\">四十九 · 与 FP8 KV 的边界：收益何时为正</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-50\">五十 · 与统一低 bit 量化的边界：残差锚点的作用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-51\">五十一 · 与稀疏注意力、投机解码的叠加关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-52\">五十二 · 打分器与淘汰器的选型判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-53\">五十三 · 分层低比特 KV 的选型边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-2bit-kv-long-video-sec-54\">五十四 · 选型边界：什么条件下该用分层2bit，而不是FP8或统一低bit</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:540px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每生成一帧，把其KV按头/通道分组，统计amax与注意力质量分数。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">近期窗口（如最近4帧）保留FP8，历史帧按重要性降到2bit或4bit，写…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">新帧注意力读出时按bit宽度分组gather，2bit组用查表去量化并加p…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对2bit组叠加一个由相邻FP8帧插值得到的残差补偿项。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">超长序列按帧级重要性淘汰最旧低分帧，控制KV池上限。</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-2bit-kv-long-video-sec-1\">一 · 一个线上事故：KV池先于算力耗尽</h3>\n<p>某长视频自回归服务在Blackwell单节点上跑一条720p、24fps、目标时长数分钟的生成链路。上线初期batch开到8，首帧时延与持续吞吐都在SLO内；运行到第若干百帧后，请求开始大面积超时，而GPU利用率并没有打满——SM的MMA流水线大量空转，HBM带宽却接近饱和。定位结果不是算力不够，而是KV池先被撑爆：自回归解码必须把历史帧的K/V持续保留以维持长程一致性，KV随帧数线性增长，单请求的KV占用很快逼近整卡容量，调度器只能不断缩小batch、甚至把请求打回排队。工程上把这种现象叫“显存墙先于算力墙”。</p>\n<p>把KV从BF16降到FP8能缓解一档，但在192GB HBM的档位上仍然不够：FP8只把每元素字节数减半，帧数继续线性叠加，池上限依旧按帧数撞顶。真正的诉求是2bit级压缩，且压缩不能破坏时空一致性——一旦历史帧的注意力读出失真，画面会出现结构漂移与场景跳变，这比OOM更难排查。本算法正是为这个具体问题设计的：在历史帧占比极高的长视频自回归里，把KV池压到FP8的1/4以下，同时用分层精度保住近期帧的读出质量。</p>\n<p>需要先把边界划清。它不解决短序列、小batch场景的吞吐问题——那里压缩收益不足以抵消去量化开销；它不解决预填阶段的算力瓶颈，也不替代分离式预填/解码的调度设计；它不改变模型权重精度，与NVFP4权重/激活量化是两条正交的路径；它更不是训练配方，重要性打分若与自回归训练分布不匹配，压缩本身会引入新的失败模式。换言之，它是一个<strong>显存换指令</strong>的算法：用注意力kernel里的查表与残差补偿，换KV池的帧数上限。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-2\">二 · 它压缩的是什么：按帧、按头、按通道分组的历史KV</h3>\n<p>数据流顺序是固定的。每生成一帧，把该帧的KV按头/通道分组，统计每组的amax与注意力质量分数；近期窗口（如最近4帧）保留FP8，历史帧按重要性降到2bit或4bit，写入压缩KV池。读出时，新帧的注意力按bit宽度分组gather，2bit组用查表去量化并加per-group scale，再叠加一个由相邻FP8帧插值得到的残差补偿项。超长序列再按帧级重要性淘汰最旧的低分帧，把KV池钉在上限内。</p>\n<p>量化与读出的形式化表达为：</p>\n<div class=\"formula\">$$q=\\mathrm{clamp}\\!\\left(\\mathrm{round}\\!\\left(\\frac{x}{s}\\right),-2^{b-1},2^{b-1}-1\\right),\\qquad \\hat{x}=q\\cdot s+r$$</div>\n<p>其中$s$是per-group scale，$b\\in\\{2,4\\}$为bit宽度，$r$为相邻FP8帧插值残差补偿。整条链路的显存账可以写成：</p>\n<div class=\"formula\">$$\\mathrm{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\qquad b_f\\in\\{2,4,8\\}$$</div>\n<p>这里$b_f$是第$f$帧每头每通道的bit宽度，$N_h$是头数，$d$是头维。关键点是$b_f$不是全局常数，而是逐帧逐头由重要性分数决定的——注意力质量高的头/帧保留更宽bit，运动剧烈的帧也倾向保留FP8。这正是它与“统一低bit量化”的分水岭：统一2bit会把所有历史帧一视同仁地压塌，而分层bit宽度让近期帧与高注意力头维持可读精度。</p>\n<p>代价必须同时记账。2bit组在注意力kernel内做查表去量化并加per-group scale，再叠加插值残差，这些是额外的指令开销；原本注意力在长序列上是带宽受限的，压缩后字节数下降，但每字节要做的运算变多，kernel可能从带宽受限翻转为计算受限。工程判断因此不是“压得越狠越好”，而是找到KV池上限与注意力kernel指令开销的平衡点：池上限决定batch与时长，指令开销决定持续吞吐。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-3\">三 · 分层bit宽度为什么必须存在：全2bit的注意力塌缩</h3>\n<p>失败模式里最危险的一条是注意力塌缩。若把历史帧全部压到2bit，或2bit组占比过高，注意力读出失去分辨力，画面失去时空结构——表现为纹理糊化、物体边界漂移、镜头切换处出现场景跳变。原因不神秘：2bit只有四个量化电平，per-group scale再精细也无法表达注意力权重的细微排序，而自回归视频的时空一致性恰恰依赖这些细微排序在数百帧上的累积。</p>\n<p>分层设计正是针对这一点。近期窗口（如最近4帧）保留FP8，因为近期帧承载了运动连续性最强的信息；历史帧按重要性降到2bit或4bit；2bit组再用相邻FP8帧插值出的残差补偿项$r$修补。这个残差项的作用是让2bit组的读出向邻居的FP8表示靠拢，相当于在时间轴上做一次轻量的误差扩散。稳定性技巧可以概括为三件套：近期帧FP8、残差补偿、帧级淘汰。三者缺一，长程一致性就会以场景跳变的形式暴露出来。</p>\n<p>重要性打分融合注意力质量与帧间运动两个信号。注意力质量高的头/帧保留更宽bit，运动剧烈的帧也倾向保留FP8——后者是因为快速运动帧的KV分布方差大，2bit的四个电平无法覆盖。这里有一个必须正视的工程风险：打分函数若与自回归训练分布不匹配，被降bit的恰好是后续帧要重点回看的帧，长程一致性下降；淘汰策略若误删关键帧，则直接造成场景跳变。打分与淘汰不是纯工程启发式，它们需要与模型的注意力统计对齐。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-4\">四 · 适用边界的量化判据：什么时候值得压</h3>\n<p>适用面可以用一句话收束：适合历史帧占比高、近期帧需高精度的长视频自回归。反过来，短序列或batch很小时，压缩收益不足以抵消去量化开销——KV池本来就没撞顶，而注意力kernel已经因为查表与残差补偿变慢，净效果是吞吐下降。规模上限由两个因素共同决定：KV池上限与注意力kernel计算开销。前者给出“能放多少帧/多大batch”，后者给出“每帧读出要多快”，两者相乘才是可服务的时长×batch。</p>\n<p>把它与相邻算法摆在一起看边界更清楚。相比FP8 KV，它把历史帧压到2bit/4bit混合并按重要性分层，收益在池上限，代价在指令开销；相比统一低bit量化，它保留近期窗口精度并用插值残差补偿，收益在一致性，代价同样是kernel开销上升。它不替代NVFP4权重/激活量化那条线，也不替代动态稀疏时空注意力——后者减少的是被读的token数，前者减少的是每个token的字节数，两者可以叠加但账要分开算。</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>是否适用</th><th>判断依据</th></tr></thead><tbody><tr><td>历史帧占比高、时长长、batch受KV池约束</td><td>适用</td><td>池上限是主瓶颈，压缩直接换来时长或batch</td></tr><tr><td>短序列、小batch</td><td>不适用</td><td>去量化与残差补偿开销大于池收益</td></tr><tr><td>注意力已接近计算受限</td><td>慎用</td><td>2bit组增多会把kernel进一步推向计算受限</td></tr><tr><td>打分/淘汰与训练分布未对齐</td><td>不适用</td><td>长程一致性下降、场景跳变风险</td></tr></tbody></table>\n<p>部署配方上，KV池按帧/头分组存储，2bit组查表去量化在注意力kernel内完成，这决定了它与tcgen05/TMEM路径的耦合方式：去量化必须贴着MMA的读出侧做，否则多一次往返就把带宽收益吃掉。192GB HBM档位下，池上限是硬约束，分层bit宽度使单卡/单节点支持更长时长或更大batch，但这一切以注意力kernel不翻转为计算受限为前提。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-5\">五 · 事故复盘落到机制：先量池，再量kernel</h3>\n<p>回到开头那条事故链路。正确的处置顺序不是先调batch，而是先量两件事：单请求KV池随帧数的增长曲线，以及注意力kernel在2bit组占比上升时的指令开销曲线。前者决定池上限能撑多少帧，后者决定持续吞吐会不会不升反降。失败模式里明确写了这一条：2bit去量化与残差补偿使注意力kernel从带宽受限转为计算受限，长序列吞吐可能不升反降——这意味着“压缩率”不是单调向好的旋钮。</p>\n<p>工程判断因此落在分层比例上：近期4帧FP8是保底，历史帧的2bit/4bit分配由重要性分数决定，2bit组占比存在一个上限，超过就触发注意力塌缩。淘汰策略则负责把池钉住，但淘汰必须按帧级重要性而非简单FIFO，否则误删关键帧就是场景跳变的直接来源。这套机制不承诺“压到2bit就万事大吉”，它承诺的是在给定池上限下，用分层精度与残差补偿把一致性损失控制在可接受范围，代价是注意力kernel的指令预算。</p>\n<p>适用边界的最终表述可以落到一个可操作的判据：当KV池上限是服务时长的约束主因、且注意力kernel尚有指令余量时，本算法是正确选择；当池未撞顶或kernel已接近计算受限时，压缩的净收益为负。这个判据不需要实验数字支撑，它由$\\mathrm{KV}_{\\text{mem}}$的求和式与kernel的受限类型共同决定——前者告诉你省了多少字节，后者告诉你这些字节换来了多少指令。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-6\">六 · 边界：它救的是显存，不是所有慢</h3>\n<p>先把失效场景摆出来。一条长视频自回归在线服务，SLO 卡在首帧时延与持续吞吐上，运维看到的是显存水位随生成帧数单调爬升：历史帧 KV 必须保留以维持长程一致性，KV 随帧数线性增长，192GB HBM 很快被吃满，batch 被迫一降再降，尾帧时延抖动。此时若直接切到统一 2bit 量化，显存是下来了，但注意力读出时 2bit 组占比过高，注意力分布塌缩，画面失去时空结构——场景跳变、主体漂移，这是比 OOM 更难排查的故障。本方案正是为这一类“历史帧占比高、近期帧仍需高精度”的负载设计的：近期窗口（如最近 4 帧）保留 FP8，历史帧按重要性降到 2bit 或 4bit 写入压缩 KV 池，读出时按 bit 宽度分组 gather，2bit 组查表去量化并加 per-group scale，再叠加由相邻 FP8 帧插值得到的残差补偿。它不解决短序列或极小 batch 的延迟问题：那种场景下压缩收益不足以抵消去量化开销，反而把带宽受限的注意力 kernel 推向计算受限。</p>\n<p>边界由两个量共同决定，而不是单一显存数字。KV 池上限给出规模天花板：</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\ b_f\\in\\{2,4,8\\}$$</div>\n<p>其中 $b_f$ 由重要性分数（注意力质量与帧间运动融合）逐帧逐头决定；注意力质量高的头、运动剧烈的帧倾向保留更宽 bit，避免全 2bit 塌缩。另一侧是 kernel 指令开销：2bit 查表去量化加残差补偿让每字节的有效算力需求上升，长序列吞吐可能不升反降。因此适用判断应写成“显存是否已成为 batch 与时长瓶颈”与“注意力是否仍带宽受限”的联合条件，任一不成立，方案收益就被抵消。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>适用</th><th>不适用/失效</th></tr></thead><tbody><tr><td>历史帧占比</td><td>高，KV 随帧数线性增长</td><td>短序列，压缩收益小于去量化开销</td></tr><tr><td>精度分层</td><td>近期 4 帧 FP8 + 历史 2/4bit 混合</td><td>全 2bit 或 2bit 组过多，注意力塌缩</td></tr><tr><td>打分与淘汰</td><td>与自回归训练分布匹配</td><td>分布不匹配，长程一致性下降、误删关键帧致场景跳变</td></tr><tr><td>kernel 状态</td><td>注意力仍带宽受限</td><td>转为计算受限，长序列吞吐不升反降</td></tr></tbody></table>\n<p>工程上还要认清它“不解决什么”：它不修复模型本身的长程建模能力，不替代并行与通信层面的扩展（NVLink 5、NCCL、NIXL 那条线另有其条目），也不保证在训练分布之外的重要性打分仍然可信。淘汰策略按帧级重要性丢弃最旧低分帧以控制 KV 池上限，一旦误删承载场景锚点的帧，跳变立刻可见。因此上线前应把打分分布与训练分布对齐作为准入条件，并把 2bit 组占比与注意力 kernel 的受限类型作为运行期监控指标，而不是只看显存水位。</p>\n<h3 id=\"alg-2bit-kv-long-video-sec-7\">七 · 逐帧写入：分组、amax 与重要性打分</h3>\n<p>长视频自回归的每一步都以“生成一帧”为原子事件。新帧的 K/V 投影完成后，kernel 首先按头与通道分组：每个头内切出固定宽度的通道组（group），组宽决定 scale 的粒度，也决定后续 LUT 的索引位宽。对每组统计 amax，得到该组的量化尺度候选；同时用本帧对历史帧的注意力分布算出注意力质量分数，再用帧间运动量（相邻帧特征差分或光流幅度）修正该分数。两者融合后写入每帧每头的 bit 宽度标签 $b_f\\in\\{2,4,8\\}$，这个标签就是压缩 KV 池的元数据。</p>\n<p>这一步的输入是新帧的 FP8/FP16 K/V 张量与注意力打分中间量，输出是“分组 scale + bit 标签 + 量化码”三元组。代价落在写侧带宽与打分开销上：分组统计要对整个 K/V 做一次归约，打分要对本帧与历史窗口做一次轻量注意力探测。在 192GB HBM 档位上，写侧带宽远未饱和，真正的压力来自打分探测引入的额外注意力计算——它随历史窗口长度增长，是这一阶段唯一随帧数上升的代价项。工程上通常把打分探测限制在降采样后的 key 上，用少量采样头估计整帧的重要性，避免每帧都做全量注意力。</p>\n<p>量化本身按 per-group scale 执行：</p>\n<div class=\"formula\">$$q=\\mathrm{clamp}\\!\\left(\\mathrm{round}\\!\\left(\\frac{x}{s}\\right),-2^{b-1},2^{b-1}-1\\right)$$</div>\n<p>其中 $s$ 为组内 scale，$b$ 取 2 或 4。2bit 组的码值域只有 $\\{-2,-1,0,1\\}$，动态范围极窄，因此 scale 的估计质量直接决定该组的信息保留率；这也是为什么分组不能太宽——组越宽，组内极值越容易把 scale 撑大，小值通道被压成零。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-8\">八 · 分层落池：近期窗口 FP8、历史帧降位</h3>\n<p>写完量化码后进入落池决策。最近 4 帧无条件保留 FP8（或 FP8/FP4 混合），因为它们是下一帧注意力的主要贡献者，精度损失会直接反映在画面连续性上。更早的历史帧按重要性分数降到 2bit 或 4bit：注意力质量高、运动剧烈的帧/头保留 4bit，其余压到 2bit。落池后的 KV 池按帧/头分组存储，物理布局上把同 bit 宽度的组连续排布，使读出阶段的 gather 能按 bit 宽度分段进行，而不是逐元素跳读。</p>\n<p>这一步的输出是压缩 KV 池与一张 bit 宽度索引表。显存代价可以直接写成：</p>\n<div class=\"formula\">$$\\mathrm{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\quad b_f\\in\\{2,4,8\\}$$</div>\n<p>与全 FP8 相比，历史帧占比越高，压缩比越接近 4 倍；但近期窗口的 FP8 帧是固定开销，它不随帧数增长而摊薄，因此当序列很短时，这部分固定开销会让整体压缩比明显低于 4 倍。这就是短序列或小 batch 下压缩收益不足以抵消去量化开销的显存侧原因。落池还引入一次元数据写：bit 标签、组 scale、帧级重要性分数都要持久化，元数据体量约为码流的百分之几，但在超长序列下同样需要按帧淘汰来回收。</p>\n<p>具体例子：一个 32 头、头维 128 的模型，单帧单头 K/V 合计约 8K 元素。若最近 4 帧保持 FP8、其余帧压到 2bit，则在历史帧占绝大多数的长序列里，每帧平均位宽被拉向 2bit 一侧；而前 4 帧始终以 8bit 计入，成为池上限公式里不可压缩的常数项。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-9\">九 · 读出 gather：按 bit 宽度分组取数与 LUT 去量化</h3>\n<p>新帧注意力读出时，Q 与整个历史 KV 池做注意力。kernel 先按 bit 宽度把 KV 池切成若干段：FP8 段直接走常规 MMA 路径，2bit 段与 4bit 段分别 gather。2bit 组的去量化用查表完成——4 个码值对应 4 个预乘 scale 的浮点值，LUT 常驻寄存器或共享内存，避免逐元素乘加。去量化结果为 $\\hat{x}=q\\cdot s+r$，其中 $r$ 是残差补偿项，在下一步单独处理。</p>\n<p>这一步的代价是本节的核心矛盾：原本注意力是带宽受限的，KV 从 FP8 压到 2bit 后，读带宽需求降到约四分之一，但每个 2bit 元素都要经历“索引 LUT、乘 scale、加残差”三条指令。当 2bit 组在 KV 池中占比很高时，算术指令数按元素计反而超过 FP8 路径的纯加载开销，注意力 kernel 从带宽受限翻转为计算受限。翻转点取决于 LUT 是否被向量化、scale 是否按组广播、以及 gather 的合并度；工程判断是：只有当 2bit 组占比超过某个阈值、且 LUT 路径已做向量化时，压缩才在端到端吞吐上兑现。否则长序列吞吐可能不升反降——这正是该机制最需要监控的失败模式。</p>\n<p>分组 gather 的伪代码思路是：按 bit 标签对 KV 池排序分段，对每段调用对应的去量化微内核，再把各段的部分注意力结果按同一 softmax 归一化合并。分段边界必须与组边界对齐，否则跨段的组 scale 会被拆散，导致同一组内元素用错 scale。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-10\">十 · 残差补偿：相邻 FP8 帧插值</h3>\n<p>2bit 组的系统性误差不是随机噪声，而是由窄动态范围造成的偏置：小值被压到零、极值被截断。纯靠提高 bit 宽度解决会吃掉压缩收益，因此机制引入插值残差补偿。对帧 $f$ 的 2bit 组，取相邻的 FP8 帧 $f-1$ 与 $f+1$ 的对应通道值做平均，作为该组的残差基准：</p>\n<div class=\"formula\">$$\\hat{K}_{f}=s_f\\cdot \\mathrm{LUT}(K^{2\\text{bit}}_{f})+\\gamma\\,(K^{\\text{FP8}}_{f-1}+K^{\\text{FP8}}_{f+1})/2$$</div>\n<p>$\\gamma$ 是补偿强度，按帧间运动量调节：运动平缓时相邻帧 KV 高度相关，插值项能有效恢复被 2bit 截断的中间值；运动剧烈时插值本身失真，$\\gamma$ 应下调，避免把错误信息注入注意力。这一步的输入是 2bit 码、组 scale 与两张相邻 FP8 帧的 KV，输出是补偿后的读出值。代价是每个 2bit 组要多读两份 FP8 邻居数据并做一次加权平均——这直接增加了读带宽，抵消了一部分压缩收益；同时它把 2bit 组的读出从“纯 LUT”变成“LUT + 邻帧加载 + FMA”，进一步加重计算受限的倾向。</p>\n<p>工程上的取舍是：只为高重要性 2bit 组开启残差补偿，低分组的 $\\gamma$ 置零，用 bit 标签旁的一个补偿标志位控制。这样既保住关键帧的时空一致性，又不让补偿开销在整池上均匀摊开。若关闭补偿，全 2bit 组占比过高会触发注意力塌缩，画面失去时空结构；若补偿过强，则等于把 2bit 路径退化成对 FP8 邻居的复制，压缩失去意义。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-11\">十一 · 帧级淘汰：控制池上限与误删风险</h3>\n<p>超长序列下，即使每帧压到 2bit，KV 池仍随帧数线性增长。机制在池达到上限时按帧级重要性淘汰最旧的低分帧：重要性分数沿用写入阶段的注意力质量与运动量融合值，淘汰顺序是先低分、再最旧，保留高分老帧以维持长程一致性。淘汰的输出是回收的显存与更新后的帧索引表；代价是一次全局排序或堆维护，以及淘汰后注意力窗口的重新分段。</p>\n<p>这一步的风险不在开销而在判断：淘汰策略若与自回归训练分布不匹配，会误删关键帧，造成场景跳变——模型在训练时见过的历史分布包含这些帧，推理时突然抽走，注意力分布随之偏移。缓解手段是把淘汰阈值与训练时的历史窗口长度对齐，并对即将被淘汰的帧做一次“降位而非删除”的过渡：先降到 2bit，再在下一轮淘汰中移除，给注意力一个适应窗口。池上限因此不是硬截断，而是“bit 宽度 + 帧数”的二维预算，二者共同决定单卡/单节点能支撑的时长与 batch。</p>\n<p>把五步串起来看，代价的分布很不均匀：写入与落池是带宽与显存主导，读出是计算主导，淘汰是元数据与策略主导。系统调优的重心因此落在读出阶段——LUT 向量化程度、gather 分段对齐、残差补偿的开关粒度，三者共同决定注意力 kernel 停留在带宽受限还是滑向计算受限。在 192GB HBM 的 Blackwell 档位上，KV 池容量给了长视频自回归以时长换 batch 的空间，但能否兑现，取决于读出路径是否把 2bit 的带宽红利真正转化为端到端吞吐，而不是被去量化指令吃掉。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-12\">十二 · 压缩路径的边界：从带宽受限滑向计算受限</h3>\n<p>这一节只谈代价与失效条件。把历史帧压到 2bit 的收益是显存，但代价落在注意力 kernel 的指令流上：读出阶段要按 bit 宽度分组 gather，2bit 组走查表去量化并乘 per-group scale，再叠加由相邻 FP8 帧插值得到的残差补偿项。量化本身是 <span class=\"formula\">$$q=\\mathrm{clamp}\\!\\left(\\mathrm{round}\\!\\left(\\frac{x}{s}\\right),-2^{b-1},2^{b-1}-1\\right)$$</span> 的逐元素操作，去量化则是 <span class=\"formula\">$$\\hat{x}=q\\cdot s+r$$</span>，其中 $r$ 是插值残差。问题在于，原本注意力是带宽受限的——KV 从 HBM 读进来就能算；压缩后字节数降到 FP8 的约四分之一，但每个 2bit 元素要额外经历查表、scale 乘法、残差加法和分组分支判断。当 2bit 组占比升高，算术强度上升，kernel 可能从带宽受限翻转为计算受限，长序列吞吐不升反降。这是压缩比与 kernel 效率之间的拐点，也是这套方案最需要盯住的系统代价。</p>\n<p>拐点位置由每帧每头的 bit 宽度分布决定。KV 池占用近似为 <span class=\"formula\">$$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\ b_f\\in\\{2,4,8\\}$$</span>，$b_f$ 是第 $f$ 帧的位宽。近期窗口（如最近 4 帧）固定 FP8，历史帧按重要性分数在 2bit 与 4bit 间分配，极少数高分帧可保留 FP8/FP4 混合。若重要性打分把过多帧判为 2bit，显存是省下来了，但注意力塌缩的风险同步上升——全 2bit 或 2bit 组占比过高会让注意力权重失去时空结构，画面出现结构漂移。反过来，若打分过于保守、4bit 与 FP8 帧太多，压缩收益不足以抵消去量化开销，192GB HBM 上的 batch 与时长上限并没有实质抬升。工程上要的是让 2bit 组占据历史帧的多数、同时把高分头/帧留在宽位宽，使 kernel 的计算增量落在可接受区间。</p>\n<p>失效条件有三类，且都与自回归训练分布绑定。其一，重要性打分融合注意力质量与帧间运动，若这套打分与模型训练时的注意力分布不匹配，被降位的帧恰好承载长程一致性信息，长程一致性下降表现为场景跳变或主体身份漂移。其二，帧级淘汰按重要性淘汰最旧低分帧以控制 KV 池上限，误删关键帧（如镜头切换的锚点帧）会直接造成跳变，且这种错误不可逆——被淘汰的 KV 无法重建。其三，残差补偿依赖相邻 FP8 帧插值，当近期窗口与历史帧的运动差异大时，插值项本身失真，2bit 组的重建误差被放大。三类失效的共同点是：压缩策略的假设（重要性可打分、邻帧可插值、旧帧可丢弃）在训练分布之外不成立。</p>\n<p>适用边界因此很清晰：历史帧占比高、近期帧需高精度的长视频自回归才值得上这套方案；短序列或 batch 很小时，去量化与残差补偿的固定开销摊不开，压缩收益不足以抵消 kernel 指令开销。规模上限由 KV 池上限与注意力 kernel 计算开销共同决定，二者取小。部署上，2bit 组查表去量化在注意力 kernel 内完成，意味着这条路径与 tcgen05/TMEM 上的 MMA 流水紧密耦合，分组 gather 的访存模式若打散合并访问，带宽优势会被抵消。判断是否启用，应先在目标 batch 与时长下测注意力 kernel 的实际受限类型，再看 2bit 组占比与长程一致性指标是否同时达标。</p>\n<h3 id=\"alg-2bit-kv-long-video-sec-13\">十三 · 量化公式的逐项拆解：从 x 到 q 再到 x̂</h3>\n<p>先把最基础的一行写清楚：<span class=\"formula\">$$q=\\mathrm{clamp}\\!\\left(\\mathrm{round}\\!\\left(\\frac{x}{s}\\right),-2^{b-1},2^{b-1}-1\\right),\\qquad \\hat{x}=q\\cdot s+r$$</span>。这行公式里真正需要工程上逐项盯住的只有四个量：<span class=\"formula\">$x$</span>、<span class=\"formula\">$s$</span>、<span class=\"formula\">$b$</span>、<span class=\"formula\">$r$</span>。$x$ 是待压缩帧某一头、某一通道组内的 KV 元素，注意它本身已经是 FP8 或 FP4 的产物，不是原始 BF16——也就是说 2bit 量化是叠加在低精度 KV 之上的二次压缩，误差预算必须按“FP8 残差 + 2bit 残差”两级来算，而不是按 BF16 直接算。$s$ 是 per-group scale，按通道分组统计 amax 得到，$b\\in\\{2,4\\}$ 是该组本次写入的 bit 宽度，$r$ 是读出时由相邻 FP8 帧插值出的残差补偿项。</p>\n<p>关键一步在 clamp 的边界：$b=2$ 时整数域是 $[-2,1]$，非对称，只有四个码字。这意味着零点不在码字中心，任何接近零的 KV 分量都会被 round 到 0 或 -1，量化台阶宽度等于 $s$，而 $s$ 由组内 amax 决定。若某组内存在一个远大于其余元素的离群值，$s$ 被它拉大，其余元素全部挤进一两个码字，组内有效分辨率崩塌。这就是为什么分组粒度必须细到“头 × 通道组”，而不是整帧一个 scale：视频 KV 的通道维度上离群通道分布随帧内容漂移，粗粒度 scale 在长视频里会持续劣化。代价上，$s$ 的元数据本身要存：每帧每头每组一个 FP16 scale，组数越多元数据占比越高，在 2bit 主体面前元数据可能反客为主，所以分组数要和 KV 池上限一起做预算，而不是无限细化。</p>\n<p>去量化侧 $\\hat{x}=q\\cdot s+r$ 的 $r$ 是这套方法区别于普通低 bit 量化的核心。普通 2bit 量化只有 $q\\cdot s$，误差是纯截断误差；这里额外加一项由时间邻域插值出来的补偿，把“当前帧这一组应当是什么”从相邻帧推断出来，相当于用时间冗余换空间分辨率。工程含义是：读出路径上多了一次插值加一次加法，且插值需要相邻帧的 FP8 KV 仍然在池中可寻址——这直接约束了帧淘汰策略不能把 2bit 组的两个 FP8 邻居都淘汰掉，否则 $r$ 无从计算。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-14\">十四 · 残差补偿项的推导：为什么是相邻帧均值</h3>\n<p>公式给出的补偿项是 <span class=\"formula\">$$\\hat{K}_{f}=s_f\\cdot \\mathrm{LUT}(K^{2\\text{bit}}_{f})+\\gamma\\,(K^{\\text{FP8}}_{f-1}+K^{\\text{FP8}}_{f+1})/2$$</span>。推导的关键一步是把帧间 KV 视为缓变信号加量化噪声：设真实 KV 为 $K_f$，2bit 量化输出为 $Q_f=s_f\\cdot\\mathrm{LUT}(q_f)$，则 $K_f=Q_f+e_f$，$e_f$ 是量化残差。假设相邻帧的残差在时间上弱相关而信号强相关，即 $K_{f\\pm1}\\approx K_f+\\Delta_{f\\pm1}$ 且 $\\Delta$ 的期望在对称邻域内抵消，那么用 $(K_{f-1}+K_{f+1})/2$ 作为 $K_f$ 的估计，其偏差只剩二阶时间差分。把该估计与量化输出做凸组合，就得到上式：$\\gamma$ 控制信任时间插值还是信任本帧 2bit 码字的比例。</p>\n<p>$\\gamma$ 不是一个可以随手设成 0.5 的常数。它应当随该组的 bit 宽度与重要性分数变化：$b=2$ 的组量化噪声大，$\\gamma$ 应偏大，让时间插值主导；$b=4$ 的组噪声小，$\\gamma$ 应偏小，避免插值把本帧的真实运动细节抹平。极端情形是运动剧烈的帧——此时 $\\Delta_{f\\pm1}$ 很大，二阶差分不再是小量，插值估计本身偏差大，正确做法是把该帧直接留在 FP8 而不是靠调 $\\gamma$ 硬撑，这正是重要性打分里“帧间运动”这一项的物理来源。代价上，$\\gamma$ 若做成 per-group 可学习或按统计量自适应，读出 kernel 就多了一次分支与一次标量乘，在注意力这种每步都要跑的路径上，标量开销会被 token 数放大。</p>\n<p>举个具体例子：某头某通道组在帧 $f$ 的 amax 使 $s_f$ 较大，2bit 码字只落在 $\\{-2,-1,0,1\\}$ 中的两个上，$Q_f$ 明显偏离真值；而 $f-1$ 与 $f+1$ 都是 FP8 且该组数值接近，插值项把 $\\hat{K}_f$ 拉回真值附近，注意力打分不至于塌缩。反过来，若 $f-1$ 已被淘汰出池，只剩 $f+1$ 单边可用，插值退化为单点复制，补偿项引入系统性偏移，这就是淘汰策略必须成对保留邻居的原因。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-15\">十五 · 重要性打分与 bit 分配的判定式</h3>\n<p>bit 宽度 $b_f$ 不是按帧龄一刀切，而是由重要性分数决定。把打分写成可实现的判定式：<span class=\"formula\">$$\\mathrm{score}_{f,h}=w_a\\cdot \\mathrm{norm}(A_{f,h})+w_m\\cdot \\mathrm{norm}(M_f),\\qquad b_{f,h}=\\begin{cases}8 &amp; \\mathrm{score}\\ge \\tau_8\\\\ 4 &amp; \\tau_4\\le \\mathrm{score}&lt;\\tau_8\\\\ 2 &amp; \\mathrm{score}&lt;\\tau_4\\end{cases}$$</span>。$A_{f,h}$ 是该帧该头在历史注意力中的质量（被后续帧读出的累计权重），$M_f$ 是帧间运动量，两个 norm 是跨帧归一化，$\\tau$ 是两档阈值。注意 $b$ 的下标是 $(f,h)$，即同一帧不同头可以有不同的 bit 宽度——这既是精度来源也是实现麻烦来源：读出时必须按头分组 gather，同一 kernel 内并行处理三种 bit 宽度。</p>\n<p>推导上值得强调的一点是阈值 $\\tau$ 的选取应当与 KV 池上限耦合，而不是独立调参。池上限给定后，总预算为 <span class=\"formula\">$$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\quad b_f\\in\\{2,4,8\\}$$</span>，其中 $N_h d$ 是每帧每层的 KV 元素数（按头与头维度计）。这是一个背包问题：在总预算约束下最大化加权注意力保真度，$\\tau$ 就是背包的拉格朗日乘子的离散化。工程上不会真去解背包，而是用固定阈值加帧级淘汰来近似，代价是预算利用率不如最优解，但换来判定式可以在生成每一帧时 O(1) 完成，不阻塞自回归主循环。</p>\n<p>系统代价在这里体现得很直接：$b_f$ 决定写入带宽与池占用。近期窗口（最近 4 帧）固定 FP8，这四帧的 KV 占用是历史帧的数倍，在 192GB HBM 档位上，窗口长度直接吃掉 batch 上限。若把窗口从 4 帧扩到 8 帧，历史帧可用的预算就被压缩，更多帧被迫落到 2bit，注意力塌缩风险上升——这是一个必须显式建模的权衡，而不是“窗口越长越好”。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-16\">十六 · 读出路径的伪代码：分组 gather 与 LUT 去量化</h3>\n<p>把读出落到可实现层面，注意力 kernel 内的流程可以写成如下伪代码思路（非 <code>&lt;pre&gt;</code>，按行叙述）：对当前 query 的头 $h$，先按 $b$ 把压缩 KV 池的帧索引分成三组——FP8 组、4bit 组、2bit 组；对每组分别 gather 对应的 K/V 块与 per-group scale 数组；FP8 组直接参与 MMA，4bit 组做移位加 scale 还原，2bit 组走 LUT：把两个 bit 平面拼成 4 个码字索引，用常量表映射到 $\\{-2,-1,0,1\\}$，乘 $s$ 后再加 $\\gamma$ 倍邻帧插值项；三组结果按原帧序拼回，再做统一的 $QK^\\top$ 与 softmax。伪代码的关键不在算术而在调度：三组的 tile 形状不同，若强行塞进同一个 tcgen05 MMA 的 K 维，就得把 2bit 组先展开成与 FP8 组同宽，展开即意味着寄存器与共享内存的额外占用。</p>\n<p>LUT 的选择有讲究。2bit 只有四个码字，LUT 可以做成寄存器常量或 shared memory 里的一张 4 项表，查表延迟被 MMA 流水掩盖；但若 LUT 输出要乘 per-group scale，则每个 group 一次标量乘，组数越多标量指令越多。这就是“注意力从带宽受限转为计算受限”的微观来源：原本读 2bit 数据省下的 HBM 带宽，被去量化的指令吞吐吃掉。判断是否翻转的分水岭在于每字节压缩数据对应的去量化指令数——当 $d$ 较小、组较细时，指令/字节比升高，翻转更容易发生。工程上的缓解手段是把 scale 吸收进 LUT（预乘成 per-group 的 4 项表），把两次操作压成一次查表，代价是表项从 4 个变成 4×组数，shared memory 占用上升。</p>\n<p>一个具体例子：某层 $N_h$ 个头，历史帧中 2bit 组占比高，读出时每个 2bit tile 需要 LUT 查表加 scale 乘加插值项三步；若该层注意力原本是带宽受限，压缩后数据量降到四分之一，但指令数增至约三倍，净效果可能是延迟不降。这正是失败模式里“长序列吞吐可能不升反降”的机制解释，也是为什么 bit 分配必须让 2bit 组占比受控，而不是能压则压。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-17\">十七 · 帧淘汰与池上限的预算式</h3>\n<p>超长序列靠帧级淘汰控制池上限。设池上限为 $C$ 字节，淘汰判据是帧级重要性分数最低且最旧者优先，写成约束式：<span class=\"formula\">$$\\text{keep}(f)=\\mathbb{1}\\left[\\mathrm{age}_f\\le L\\ \\lor\\ \\mathrm{score}_f\\ge \\tau_{\\text{evict}}\\right],\\qquad \\sum_{f\\in\\text{keep}} b_f N_h d\\le C$$</span>。$L$ 是保留窗口长度，$\\tau_{\\text{evict}}$ 是淘汰阈值。这个式子的工程难点在于两个条件会打架：一帧可能很旧但注意力质量极高（长程一致性依赖它），按 age 该淘汰，按 score 该保留。若实现里只按 age 淘汰，就会出现“误删关键帧造成场景跳变”的失败模式；若只按 score，则低分帧永远占着池子，新帧写不进来。</p>\n<p>推导上的关键一步是把淘汰做成“先写后删”而非“先删后写”：新帧 KV 先按打分写入，触发池上限时再按 keep 判据回收，保证任何时刻池内帧集合满足预算约束，且被淘汰帧的 2bit 邻居关系在回收时一并检查——若某 2bit 帧的两个 FP8 邻居之一被淘汰，该 2bit 帧的残差补偿项失效，应同步降级或提升其 bit 宽度。这一步在实现上是池管理器的引用计数，代价是每次写入多一次邻居检查，属于控制面开销，不进入注意力热路径。</p>\n<p>系统代价方面，池上限 $C$ 与 batch 是直接竞争关系：$C$ 越大单请求可容纳时长越长，但留给并发的显存越少。在 192GB HBM 上做容量规划时，应把 $C$ 按“目标时长 × 每帧平均 bit 宽度 × 头数 × 头维度”反推，再留出近期 FP8 窗口与元数据的余量，而不是先定 batch 再看能跑多长。SLO 以首帧时延与持续吞吐为主时，池上限的设定还要考虑淘汰触发的抖动——淘汰发生在解码步内会引入不规则延迟尖峰，把淘汰挪到步间或按批摊销是常见做法。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-18\">十八 · 稳定性条件与失败模式的公式化表述</h3>\n<p>把三条失败模式写成可检查的条件，比定性描述更有用。第一条，注意力塌缩：当 2bit 组占比 $\\rho=\\sum_{b_f=2}N_h d/\\sum_f b_f N_h d$ 超过某阈值时，softmax 的输入分布被量化噪声展宽，注意力权重趋于均匀，时空结构丢失。可检查的量是读出后 $QK^\\top$ 的熵相对 FP8 基线的偏移，偏移超限即触发把部分 2bit 组升到 4bit。第二条，残差补偿失效：当某 2bit 组的两个 FP8 邻居不同时在池中，$\\gamma$ 项退化为单边，补偿变成偏移，可检查的量是该组 $\\hat{x}$ 与邻帧插值估计的残差符号一致性。第三条，淘汰误删：被淘汰帧若在后续若干帧的注意力质量排名中仍居前，说明 $\\tau_{\\text{evict}}$ 与训练分布不匹配，可检查的量是淘汰后若干步内的注意力质量回查。</p>\n<p>稳定性技巧的组合是“近期 FP8 + 残差补偿 + 帧级淘汰”，三者不是独立开关而是互相约束：残差补偿要求邻居在池，淘汰要求预算，FP8 窗口吃掉预算。工程判断上，这套方法的适用边界由两个量共同决定——KV 池上限与注意力 kernel 的计算开销。历史帧占比高、近期帧需高精度的长视频自回归是它的甜点区；短序列或 batch 很小时，压缩省下的显存换不来吞吐，去量化开销反而成为净损失。落到具体机制上，决定是否启用的判据应是“每步注意力的指令/字节比是否仍低于带宽受限阈值”，低于则压，高于则不压——这条判据比任何固定 bit 配方都更能适应不同模型与序列形态。</p>\n<h3 id=\"alg-2bit-kv-long-video-sec-19\">十九 · 请求形态：谁该走这条路径</h3>\n<p>2bit KV 分层量化的收益不是均匀分布的，它只对一类请求形态成立：<strong>历史帧占比高、近期帧需要高精度、单请求时长足够长</strong>的自回归视频在线生成。判断一个请求是否落在配方内，看三个比例而非绝对长度——历史帧 KV 占 KV 池的比例、近期窗口（最近 4 帧 FP8）占全部 KV 的比例、以及 2bit 组在注意力读出中占的 gather 比例。前两个比例高、第三个比例落在中等区间，压缩收益才盖得住去量化开销。若历史帧只占 KV 池的一小部分，2bit 压缩省下的显存不足以换来更大 batch，反而白付了 LUT 查表与残差补偿的指令成本。</p>\n<p>请求形态上，它适合连续、单调延长的单条长视频会话：镜头内运动连贯、场景切换稀疏、帧间运动量分布平稳。这类负载的重要性打分（注意力质量 + 帧间运动）在时间轴上平滑，帧级淘汰不会误删关键帧。反之，高频切镜、每几帧一次场景跳变的请求，运动分数剧烈抖动，打分器会把大量帧误判为高重要性而保留 FP8，压缩率塌回 FP8 水平，等于没压。</p>\n<p>工程上要给出的判据是：一个请求进入 2bit 分层路径前，先看它的历史帧 KV 是否已经超过 KV 池上限的某个比例阈值，以及近期窗口是否能稳定容纳最近 4 帧 FP8。两个条件同时满足才启用分层；否则退回 FP8 KV 或统一 4bit，避免为不匹配的形态支付 kernel 指令税。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-20\">二十 · 长度分布：KV 池上限决定 batch 与时长</h3>\n<p>长度分布直接映射到 KV 池占用。按帧计，KV 显存近似为</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\ b_f\\in\\{2,4,8\\}$$</div>\n<p>其中 $b_f$ 是该帧每头的 bit 宽度，$N_h$ 是头数，$d$ 是头维。分层策略把 $b_f$ 在 2/4/8 之间按重要性分配，近期 4 帧固定为 8bit（FP8），历史帧按打分降到 2bit 或 4bit。于是 KV 池上限不再由“最长可能时长”决定，而由“帧级淘汰后保留的加权 bit 总量”决定。192GB HBM 档位上，这个上限同时约束两件事：单请求可达时长，以及同卡并发 batch。</p>\n<p>长度分布的形状比均值更重要。若请求时长集中在短尾（几十帧量级），历史帧本来就少，2bit 组占比低，去量化开销摊不薄，压缩收益不足以抵消 kernel 从带宽受限转为计算受限的代价。若分布是长尾重载——大量请求超过数百帧——KV 池被历史帧填满，此时分层量化的边际收益最大，但也最容易被帧级淘汰策略的误判拖垮：淘汰阈值设得激进，长尾请求会反复触发场景跳变；设得保守，KV 池上限被顶穿，batch 被迫缩小。</p>\n<p>因此长度分布的配方要求是：按分位数而非均值做容量规划，用 P90/P99 时长估算历史帧 KV 的加权 bit 总量，再反推单卡可承载的并发数。短尾请求应路由到不启用量化的路径，长尾重载请求才进分层池。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-21\">二十一 · 并发与批大小：SLO 是首帧时延加持续吞吐</h3>\n<p>这条路径的 SLO 不是单一指标，而是首帧时延与持续吞吐的组合。首帧时延由预填与首帧解码决定，与 KV 量化基本无关；持续吞吐才是量化真正影响的量。分层量化把 KV 读带宽压下来，理论上允许更大 batch，但去量化与残差补偿把注意力 kernel 推向计算受限，batch 增大到某一点后，每 token 的注意力时间不再随带宽下降而下降，吞吐曲线出现拐点。</p>\n<p>批大小的配方因此不是“越大越好”，而是找一个使注意力 kernel 仍处于带宽受限侧的批大小。伪代码思路：</p>\n<ul>\n<li>对候选 batch $B$，估算单步注意力读字节 $\\approx B\\cdot\\sum_f b_f N_h d$，与去量化指令数 $\\approx B\\cdot n_{2\\text{bit}}\\cdot c_{\\text{LUT}}$ 并列；</li>\n<li>若读字节对应的带宽时间 &gt; 指令时间，kernel 带宽受限，加 batch 仍线性增益；</li>\n<li>若指令时间反超，进入计算受限区，加 batch 只增加排队时延，持续吞吐饱和；</li>\n<li>取拐点前一个档位作为稳定 batch，并把超出部分路由到第二张卡或第二节点。</li>\n</ul>\n<p>并发维度还要区分“同卡多请求”与“单请求长时长”。前者共享 KV 池上限，后者独占池但拉长帧级淘汰链。工程判断是：并发数按池上限除以 P90 请求的加权 bit 占用来定，而不是按显存空余字节粗算；否则长尾请求一进来就把池顶穿，触发淘汰风暴。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-22\">二十二 · 负载不对时：三种可观测的退化</h3>\n<p>负载与配方错配时，退化是可观测的，不是玄学。第一种是<strong>吞吐不升反降</strong>：短序列或小 batch 场景下，2bit 去量化与残差补偿的指令开销压过带宽节省，注意力 kernel 从带宽受限转为计算受限，长序列吞吐低于纯 FP8 路径。表现为单步注意力时间随帧数增长出现非单调抬升，而 KV 读字节明明在下降。</p>\n<p>第二种是<strong>注意力塌缩</strong>：2bit 组占比过高（历史帧几乎全降 2bit，近期窗口又被淘汰策略侵蚀），去量化后的 KV 与残差补偿不足以维持时空结构，注意力分布扁平化，画面失去连贯运动。这是全 2bit 的典型失败，分层 bit 宽度与残差补偿正是为压制它而存在；一旦负载让 2bit 组比例失控，保护机制失效。</p>\n<p>第三种是<strong>场景跳变</strong>：帧级淘汰误删关键帧。当重要性打分与自回归训练分布不匹配——例如推理请求的运动统计与训练时差异大——打分器把低分但语义关键的帧淘汰，长程一致性断裂，输出出现突兀切镜。这类退化在监控上表现为帧间运动分数突变与注意力质量分数的离群点，可作为路由回退的触发信号。</p>\n<p>三种退化共享一个根因：负载形态让分层策略的假设失效。配方不是普适开关，而是带前提的路径选择。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-23\">二十三 · 路由与回退：把配方写成判定表</h3>\n<p>把上述判据落成工程判定表，比在 kernel 里做自适应更可控。判定输入是请求的历史帧占比、近期窗口可容纳性、P90 时长分位、以及当前卡的注意力 kernel 受限侧。输出是三档路径：分层 2bit、统一 4bit、纯 FP8。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>路径</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>历史帧占比高、时长长尾、运动平稳</td><td>分层 2bit（近期 4 帧 FP8）</td><td>去量化指令开销，需控 batch 在拐点前</td></tr>\n<tr><td>时长中等、历史帧占比中等</td><td>统一 4bit</td><td>压缩率有限，但 kernel 指令开销低</td></tr>\n<tr><td>短序列、小 batch、高频切镜</td><td>纯 FP8</td><td>KV 池上限低，但无去量化税</td></tr>\n</tbody></table>\n<p>回退触发条件要写死：注意力 kernel 受限侧翻转为计算受限、2bit 组占比超过设定上限、帧间运动分数出现离群突变，任一命中即把该请求或该 batch 降档。回退粒度建议按请求而非按卡，避免一条异常请求拖垮同卡其他长尾会话。</p>\n<p>容量规划侧，用判定表反推每档路径的加权 bit 占用，再按 P90 并发估算池上限。192GB HBM 档位上，分层路径的池上限由帧级淘汰保留的加权 bit 总量决定，而不是由最长时长决定；这把容量规划从“按最长请求预留”改成“按分位分布预留”，是配方真正的工程价值。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-24\">二十四 · 与训练分布的耦合：打分器是配方的隐藏前提</h3>\n<p>重要性打分融合注意力质量与帧间运动，它决定了每帧每头的 bit 宽度分配。这个打分器的统计特性必须与自回归训练分布匹配，否则整个分层结构建立在错误的优先级上。负载不对时最常见的隐性错配是：推理请求的运动幅度分布比训练时更宽，打分器把大量帧判为高运动、保留 FP8，压缩率塌回 FP8；或反过来，运动被低估，关键帧被降 2bit，塌缩与跳变同时出现。</p>\n<p>工程上可做的不是在线重训打分器，而是把打分输出的分布当作可观测指标：统计每请求的 2bit/4bit/FP8 帧占比与注意力质量分数的分位，与训练分布基线比对。偏离超过阈值即判定该请求形态不在配方内，路由到统一 4bit 或纯 FP8。这把“负载是否匹配”从主观判断变成分布比对，也让帧级淘汰阈值可以按分布而非固定常数设定。</p>\n<p>最终落在具体机制上：分层 2bit 的收益上限由 KV 池上限与注意力 kernel 受限侧共同封顶，而这两者都由负载的长度分布、并发形态与打分器分布决定。配方写对了，192GB 档位上的单卡或单节点能撑起更长时长与更大 batch；配方写错，去量化税与淘汰误判会把收益吃回去。判定表与分布比对是这条路径能否稳定兑现的前提，而不是可选项。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-25\">二十五 · 负载配方与失效边界：这套方案在什么请求形态下才划算</h3>\n<p>这套分层 2bit KV 方案的收益不是无条件的，它由请求的<strong>历史帧占比</strong>决定。设单请求总帧数为 <em>F</em>、近期窗口为 <em>W</em>（如最近 4 帧），则历史帧占比 <em>ρ</em>=(<em>F</em>−<em>W</em>)/<em>F</em>，压缩收益近似正比于 <em>ρ</em>·(1−<em>b</em><sub>hist</sub>/8)。<em>F</em> 只有几十帧时 <em>ρ</em> 很小，2bit 组带来的显存节省抵不过注意力 kernel 里查表去量化与残差补偿的指令开销；只有当 <em>F</em> 达到数百帧、历史帧在 KV 池中占绝对多数时，压缩才真正把 192GB HBM 上的 batch 与时长上限推开。因此负载配方应把长视频在线请求作为主场景，短序列、小 batch 的请求走 FP8 路径更稳。</p>\n<p>并发维度上，KV 池上限是硬约束而非软约束：<em>KV</em><sub>mem</sub>≈Σ<sub>f</sub> <em>b</em><sub>f</sub><em>N</em><sub>h</sub><em>d</em>，<em>b</em><sub>f</sub>∈{2,4,8}。批大小与时长是同一笔预算的两种花法——加大 batch 就要缩短每请求保留的帧数，延长时长就要牺牲并发。工程上应按帧级重要性淘汰最旧低分帧来给池子封顶，并把 batch 调度器与淘汰阈值联动：当池占用逼近上限时优先拒绝新长请求，而不是让淘汰策略被动误删关键帧。SLO 上以首帧时延与持续吞吐为主指标，因为去量化开销落在 decode 阶段的每一步注意力里，直接体现为持续吞吐而非首帧。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>压缩收益</th><th>主要代价</th><th>判断</th></tr></thead><tbody><tr><td>数百帧以上、历史帧占多数</td><td>显存显著下降，batch/时长上限抬升</td><td>注意力 kernel 指令开销</td><td>推荐启用分层 2bit</td></tr><tr><td>短序列、batch 很小</td><td>收益不足以抵消开销</td><td>去量化固定成本占比高</td><td>退回 FP8</td></tr><tr><td>运动剧烈、镜头切换频繁</td><td>2bit 组易塌缩</td><td>长程一致性下降、场景跳变</td><td>提高 FP8 保留比例</td></tr></tbody></table>\n<p>失效条件集中在三处。其一是重要性打分与自回归训练分布不匹配：打分融合注意力质量与帧间运动，若推理时的运动统计偏离训练分布，高分帧被误降为 2bit，长程一致性下滑。其二是 2bit 组占比过高导致注意力塌缩，画面失去时空结构，这要求给 2bit 组比例设上限并用残差补偿兜底。其三是 kernel 从带宽受限转为计算受限——长序列吞吐可能不升反降，此时应下调 2bit 组比例或缩短近期窗口外的分层粒度，用带宽换回指令预算。</p>\n<h3 id=\"alg-2bit-kv-long-video-sec-26\">二十六 · 硬件档位与KV池的物理边界</h3>\n<p>在Blackwell 192GB HBM这一档位上，部署配方的第一件事不是选框架，而是把KV池的字节预算算成帧数。压缩KV池的占用由 <span class=\"formula\">$$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\ b_f\\in\\{2,4,8\\}$$</span> 给出：逐帧求和，每帧的bit宽度$b_f$由重要性分层决定，$N_h d$是该帧所有头的通道总量。这条式子决定了三件事必须一起定：帧数上限、每帧平均bit宽度、以及留给权重与激活的余量。工程上的做法是先固定权重与运行时开销的占用，把剩余显存全部划给压缩KV池，再反解出可容纳的帧数上限——这个上限就是batch与时长联合调度的硬约束，而不是软目标。</p>\n<p>档位划分按$b_f$的分布来定，而不是按模型大小。若近期窗口固定为最近4帧保留FP8（$b_f=8$），历史帧主体落在2bit（$b_f=2$），少量中重要性帧落在4bit，则平均bit宽度由历史帧中2bit与4bit的比例决定。把4bit帧占比压到很低时，KV池可压到FP8的1/4以下，这是本方案在单卡上换取时长与batch的唯一来源。反过来，若重要性打分把大量帧判为4bit，压缩比迅速退化，192GB的边界会重新变成瓶颈。因此部署时必须把“4bit帧占比”当作一个可观测的运行指标，而不是事后统计。</p>\n<p>具体例子：一个以帧为单位的自回归请求，近期4帧FP8、其余历史帧绝大多数2bit、仅少数运动剧烈帧升到4bit，则KV池的增长斜率约为全FP8方案的几分之一，单卡可容纳的帧数随之抬升；但这条斜率对4bit帧占比极其敏感，占比翻倍即意味着池上限明显下移。部署配方因此把“帧级bit预算”做成显式配置项，而不是让打分器自由发挥。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-27\">二十七 · 并行拓扑：把查表去量化放在哪一层</h3>\n<p>2bit组的读出路径是<span class=\"formula\">$$\\hat{K}_{f}=s_f\\cdot \\mathrm{LUT}(K^{2\\text{bit}}_{f})+\\gamma\\,(K^{\\text{FP8}}_{f-1}+K^{\\text{FP8}}_{f+1})/2$$</span>，查表去量化加per-group scale，再叠加相邻FP8帧插值得到的残差补偿。这条路径必须落在注意力kernel内部完成，否则压缩收益会被额外的中间张量写回吃掉。拓扑选择的核心问题是：按头切分还是按帧切分。</p>\n<p>按头切分（TP）让每个rank持有全部帧的部分头，好处是单帧内的注意力计算本地完成，残差补偿所需的相邻帧FP8数据也在同一rank上；代价是每帧的KV池被切碎，帧级淘汰需要跨rank同步重要性分数。按帧切分（序列/帧并行）让每个rank持有一段连续帧，帧级淘汰与bit分层天然本地化，但新帧注意力要跨rank gather历史KV，通信量随帧数线性上升，NVLink 5的带宽成为新的约束项。工程判断是：当帧数上限由KV池决定而非由通信决定时选按头切分；当单请求帧数极长、单rank池装不下时选按帧切分，并把2bit组的gather做成按bit宽度分组的批量传输，避免逐帧小包。</p>\n<p>另一条拓扑决策是预填与解码是否分离。长视频自回归的预填阶段要处理历史帧KV的写入与分层，解码阶段只做单帧读出，两者的资源画像不同：预填偏带宽与显存写入，解码偏kernel指令开销。把预填放在独立实例上，可以让解码实例的KV池布局与bit分层策略保持稳定，不被预填的瞬时写入压力打乱。这与分离式预填/解码的一般做法一致，此处只强调一点：分层bit宽度必须在两侧用同一份重要性打分口径，否则预填写入的bit宽度与解码读出的假设不一致，残差补偿会失配。</p>\n<p>代价上要盯住一个转折点：2bit去量化与残差补偿增加指令开销，注意力kernel可能从带宽受限转为计算受限。拓扑上表现为SM占用率上升而HBM吞吐下降。部署时用一个判据——若注意力kernel的实测吞吐随batch增大不再线性上升，说明已进入计算受限区，此时继续加batch只会拉长单帧时延，应改为降低2bit组占比或缩短残差补偿的插值范围。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-28\">二十八 · 量化方案：分层bit宽度与打分口径</h3>\n<p>量化本身用<span class=\"formula\">$$q=\\mathrm{clamp}\\!\\left(\\mathrm{round}\\!\\left(\\frac{x}{s}\\right),-2^{b-1},2^{b-1}-1\\right)$$</span>，$s$为per-group scale，$b\\in\\{2,4\\}$，读出时$\\hat{x}=q\\cdot s+r$。分组维度是头与通道，per-group scale意味着每帧每头可以独立选择bit宽度而不破坏张量布局。部署配方要固定三件事：分组粒度、近期窗口长度、以及重要性打分的融合权重。</p>\n<p>分组粒度决定scale的元数据开销。分组越细，量化误差越小，但每组的scale与残差项都要存储与读取，元数据在2bit主体面前占比不可忽略。工程上取通道方向的中等分组，使scale开销相对2bit主体保持可控，同时让同一头内不同通道的运动差异能被分层捕捉。近期窗口固定为最近4帧保留FP8，这是一个硬边界：窗口内的帧不参与降bit，保证当前生成帧的注意力读出有高精度锚点。</p>\n<p>重要性打分融合注意力质量与帧间运动：注意力质量高的头/帧保留更宽bit，运动剧烈的帧也倾向保留FP8，避免全2bit导致的注意力塌缩。打分口径必须与自回归训练分布匹配，这是失败模式之一——打分器若在训练分布外把关键帧判为低分，长程一致性会下降并出现场景跳变。部署上把打分做成两级：帧级分数决定$b_f$的档位，头级分数在同一帧内做微调，两级都设上限，防止单帧独占bit预算。</p>\n<p>残差补偿项$r$由相邻FP8帧插值得到，$\\gamma$是插值权重。它的作用是给2bit组补回被量化抹掉的低频成分，代价是每次读出要多一次相邻帧数据的访问。若相邻帧已被淘汰或本身也是2bit，插值源失效，补偿退化为零——这是淘汰策略必须与残差补偿联动的原因：淘汰最旧低分帧时，要保证被淘汰帧不作为任何保留帧的插值源，否则补偿链断裂。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-29\">二十九 · KV策略：淘汰、上限与稳定性三联</h3>\n<p>超长序列按帧级重要性淘汰最旧低分帧以控制KV池上限。淘汰不是独立策略，它与bit分层、残差补偿构成三联：淘汰决定哪些帧还在池里，bit分层决定剩下帧的宽度，残差补偿依赖相邻帧的存在。三者任一处口径不一致，稳定性技巧（近期帧FP8加残差补偿加帧级淘汰）就会失效。</p>\n<p>淘汰的判据要同时看分数与年龄。只看分数会误删早期但结构关键的帧，造成场景跳变；只看年龄会把运动剧烈的高分帧一起扔掉。工程做法是设一个年龄窗口，窗口外的帧才进入淘汰候选，候选内按分数排序，并保留一个“插值源保护集”——任何被保留帧所依赖的相邻FP8帧不进入淘汰。这个保护集的大小直接决定KV池的有效上限，是部署时必须显式配置的参数。</p>\n<p>KV池上限一旦设定，batch与时长就成为联合约束下的两个变量。负载配方里SLO以首帧时延与持续吞吐为主，因此调度参数要围绕这两个指标分配：首帧时延由预填阶段的历史帧写入与分层决定，持续吞吐由解码阶段的注意力kernel是否计算受限决定。具体例子：当请求时长接近池上限时，淘汰开始频繁触发，每次淘汰都要重算受影响帧的插值源，这段开销计入解码时延；若淘汰频率随帧数上升，持续吞吐会出现台阶式下降，此时应提前收紧bit预算或降低batch，而不是等池打满。</p>\n<p>稳定性还要防另一种失败：2bit组过多使注意力塌缩，画面失去时空结构。部署侧的护栏是给2bit组占比设上限，超过上限时强制把部分帧升到4bit，用显存换一致性。这条护栏与压缩目标直接冲突，因此它的阈值应作为SLO的一部分对外承诺，而不是内部随意调整。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-30\">三十 · 调度参数与可复现的配置思路</h3>\n<p>调度参数分三层：请求准入、帧级bit预算、以及kernel执行配置。请求准入按KV池剩余容量与当前4bit帧占比决定是否接纳新请求，而不是按空闲显存——因为显存空闲不等于池有余量，池的余量由帧数与bit分布共同决定。帧级bit预算在请求准入时按负载配方给定初值，运行中按重要性打分动态调整，但调整幅度受限，避免单帧抖动引发全局重排。</p>\n<p>kernel执行配置的核心是分组gather的批量化。读出时新帧注意力按bit宽度分组gather，2bit组与4bit组、FP8组分别成批处理，查表去量化在kernel内完成。分组越整齐，指令流水越顺；若bit宽度在同一批次内频繁交错，kernel会反复切换路径，指令开销上升。因此调度上倾向于让同一批次内的请求共享相近的bit分布，把bit分布差异大的请求错峰，这是一条纯工程性的吞吐优化，与量化算法本身无关。</p>\n<p>可复现的配置思路按以下顺序落地：第一步，固定192GB档位下权重与运行时开销的占用，反解KV池字节预算；第二步，按最近4帧FP8、历史帧2bit为主、4bit为辅设定初始bit分布，并算出对应的帧数上限；第三步，选并行拓扑，帧数上限受池约束时按头切分，单rank池装不下时按帧切分并批量gather；第四步，设淘汰年龄窗口与插值源保护集，把保护集大小计入池上限；第五步，设2bit组占比护栏与计算受限判据，前者保一致性，后者保吞吐；第六步，把首帧时延与持续吞吐作为SLO，按池余量与bit占比做准入。</p>\n<p>这套顺序的关键在于每一步都用一个可观测的量收口：池字节预算、帧数上限、4bit帧占比、保护集大小、2bit组占比、注意力kernel是否计算受限。任何一个量偏离配置区间，都对应一个明确的动作——收紧bit预算、调整拓扑、或降低batch——而不是靠调参试错。适用边界也要写进配置：短序列或batch很小时，压缩收益不足以抵消去量化开销，此时应绕过分层量化走FP8路径；规模上限由KV池上限与注意力kernel计算开销共同决定，两者中先触顶的那个就是这套配方的真实天花板。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-31\">三十一 · 边界条件：压缩收益何时被去量化开销吃掉</h3>\n<p>这套分层KV方案的收益并非单调。设历史帧占比为 $\\rho$，2bit组在注意力读出的总元素中占比为 $\\kappa$，则注意力单步时间可粗写为 $T_{\\text{att}}\\approx \\max\\!\\big(T_{\\text{bw}}(\\rho,\\kappa),\\,T_{\\text{alu}}(\\kappa)\\big)$：前者随KV字节数下降，后者随查表去量化与残差补偿的指令数上升。当 $\\kappa$ 越过某条曲线交点，kernel 从带宽受限翻转为计算受限，长序列吞吐不升反降——这正是本方案最需要盯住的失效条件。Blackwell 192GB HBM 档位上，短序列或 batch 很小时 $\\rho$ 低，压缩省下的字节不足以抵消 LUT 与插值残差的固定开销，收益为负，应直接退回 FP8 KV 路径。</p>\n<p>第二个边界是分布匹配。重要性分数融合注意力质量与帧间运动，若打分函数与自回归训练分布不一致，被压到2bit的历史帧恰好是后续帧真正依赖的那批，长程一致性下降并以场景跳变的形式暴露。工程上应把打分统计与淘汰阈值当作可观测指标（每帧被降bit比例、被淘汰帧的注意力质量分位），而不是一次性写死的常量。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>系统表现</th><th>处置</th></tr></thead><tbody><tr><td>$\\kappa$ 高、历史帧占比高</td><td>注意力转计算受限，吞吐下降</td><td>限制2bit组比例，近期窗口扩至更多帧</td></tr><tr><td>batch 小、序列短</td><td>去量化开销占比大</td><td>跳过压缩，走 FP8/FP4 混合</td></tr><tr><td>打分分布漂移</td><td>关键帧被误删，场景跳变</td><td>淘汰前做重要性复核，保留最低配额</td></tr></tbody></table>\n<p>第三个边界是KV池上限与并行的耦合。$\\text{KV}_{\\text{mem}}\\approx\\sum_f b_f N_h d$ 中 $b_f\\in\\{2,4,8\\}$ 由帧级重要性决定，池上限一旦按最坏情况（全FP8）预留就失去压缩意义，按平均bit宽度预留则会在运动剧烈片段触发淘汰。可复现的配置思路是：先按目标时长与batch反解出允许的平均 $b_f$，再据此设定近期窗口长度与2bit组占比上限，把淘汰策略作为最后一道阀门而非首选手段；并行拓扑上优先保证单卡内KV池可控，跨节点扩展只在单卡池已压到上限、且注意力仍处带宽受限区时才划算。</p>\n<h3 id=\"alg-2bit-kv-long-video-sec-32\">三十二 · 显存账本：KV池上限先于HBM容量触顶</h3>\n<p>在192GB HBM的Blackwell档位上，长视频自回归的KV池并不是“用到显存不够为止”，而是被一个显式的池上限提前截断。按帧/头分组存储后，占用由 <span class=\"formula\">$$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\ b_f\\in\\{2,4,8\\}$$</span> 决定，其中 $b_f$ 是该帧每头的bit宽度。这条式子的工程含义是：池上限不是常数，而是bit宽度分布的积分。近期窗口固定为最近4帧保留FP8（$b_f=8$），历史帧按重要性落到2bit或4bit，于是同一时长下KV池大小取决于“有多少帧被判为高重要性”。重要性打分一旦偏向保守（注意力质量阈值设低、运动判据放宽），4bit帧占比上升，池上限对应的可容纳时长与batch同步缩水，这是规模上去后第一个崩点：不是显存耗尽报OOM，而是调度器按池上限拒绝新请求，有效batch被压到SLO无法满足的水平。</p>\n<p>具体例子：一个持续在线请求，每帧每头KV若全FP8占用为基准1，历史帧全压到2bit则降到1/4以下；但只要有三成帧因运动剧烈被判为4bit，整体压缩比就从4×回落到约2.3×，池上限对应的最大帧数下降近一半。工程判断是：池上限必须按“最坏bit分布”预留，而不是按平均压缩比预留，否则尾延迟会在长请求上集中爆发。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-33\">三十三 · 带宽与计算的角色互换：去量化把注意力推过拐点</h3>\n<p>压缩本身是带宽优化：2bit组让注意力读出的字节数降到FP8的1/4，长序列解码阶段原本带宽受限的注意力理应更快。但读出路径不是纯搬运——2bit组要用查表去量化并乘per-group scale，还要叠加由相邻FP8帧插值得到的残差补偿项 $\\gamma\\,(K^{\\text{FP8}}_{f-1}+K^{\\text{FP8}}_{f+1})/2$。每读一个2bit组，kernel要多做一次LUT gather、一次scale乘、一次插值加，指令数随2bit组占比线性上升。当2bit组占比超过某个拐点，注意力kernel从带宽受限翻转为计算受限，此时继续压bit不再提速，反而因为指令开销拖慢单帧解码。</p>\n<p>代价可以直接写成两个时间项的竞争：<span class=\"formula\">$$T_{\\text{attn}}\\approx \\max\\!\\left(\\frac{B_{\\text{read}}}{BW},\\ \\frac{I_{\\text{inst}}}{IPC\\cdot f}\\right)$$</span> 压缩降低 $B_{\\text{read}}$ 却抬高 $I_{\\text{inst}}$。规模上去后，长序列的 $B_{\\text{read}}$ 项被压得很低，$I_{\\text{inst}}$ 项成为主导，这就是“长序列吞吐可能不升反降”的机制来源。工程上必须按2bit组占比做kernel分档：低占比走统一去量化路径，高占比走分组gather加向量化LUT，避免单一kernel在两种负载下都次优。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-34\">三十四 · 通信：分层bit宽度改变的是all-gather的字节结构</h3>\n<p>在NVL72这类单节点域内，张量并行与序列并行下的KV交换走NVLink 5，通信量正比于KV字节数。分层bit宽度带来的不是均匀缩小，而是字节结构的不均匀：近期4帧的FP8块保持原尺寸，历史2bit块缩到1/4。all-gather与reduce-scatter的代价因此由“最宽的那一段”与“块数”共同决定，而非平均bit宽度。若按帧粒度切分通信块，2bit帧与FP8帧混在一个collective里，collective的完成时间被FP8段拉长，压缩收益在通信侧被稀释。</p>\n<p>具体做法是按bit宽度分通道：2bit帧走独立的低字节collective，FP8近期窗口走另一条，二者在注意力读出前于本地拼合。代价是collective数量上升、启动开销增加；在NVL72内这一开销可被NVLink 5的高带宽摊薄，但跨节点分离式部署时，NIXL传输的元数据与块描述符开销会随分组数上升。规模上去后通信侧先崩的位置是分组过多导致的collective碎片化，而不是总字节数。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-35\">三十五 · 功耗与持续吞吐：解码阶段的能效拐点</h3>\n<p>2bit去量化是查表加乘加，属于低算术强度的整数/查表混合负载，单位字节的能耗高于纯拷贝，但低于FP8 MMA。持续吞吐场景下，功耗约束体现为SM可维持的时钟与活跃SM数：当2bit组占比高、kernel计算受限时，SM占用率上升、时钟被功耗墙压低，单帧解码时间拉长，持续吞吐下降。这与显存侧的收益形成对冲——显存省下来了、batch可以更大，但每帧的计算能耗上升，整机吞吐未必线性增长。</p>\n<p>工程判断是把残差补偿的插值项做成可关闭的档位：在功耗受限的部署里，对重要性分数处于中间带的帧关闭插值补偿、只保留per-group scale去量化，用少量一致性损失换回计算开销；对高重要性帧保留完整补偿。这个档位切换必须与帧淘汰策略联动，否则关掉补偿的帧在后续淘汰中容易被误判为低分而删除，造成场景跳变。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-36\">三十六 · 尾延迟：淘汰策略与池上限的耦合是抖动源</h3>\n<p>首帧时延与持续吞吐是这类在线请求的SLO主轴，而尾延迟的抖动几乎全部来自帧级淘汰。超长序列按帧级重要性淘汰最旧低分帧以控制池上限，淘汰发生在解码循环内，触发一次KV池重排与索引重建。重排本身是显存写操作，代价随池大小上升；更关键的是淘汰判据与自回归训练分布不匹配时，关键帧被误删，后续注意力读出被迫在缺失上下文上做插值补偿，画面出现跳变，用户侧表现为长请求尾部的质量抖动而非时延抖动。</p>\n<p>具体机制上，淘汰应做成惰性标记加后台压缩：解码循环只把帧标为可淘汰，实际重排推迟到池占用越过水位线时批量执行，把重排代价从每帧摊到每批。代价是池上限需要预留水位余量，等效压缩比下降；收益是尾延迟的方差收敛。规模上去后，尾延迟先崩的位置通常是淘汰重排与解码循环争抢显存带宽，而不是注意力kernel本身。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-37\">三十七 · 规模上去以后哪里先崩：三个次序</h3>\n<p>把上述代价按规模排序，崩溃次序大致是：先池上限拒绝请求（显存账本按最坏bit分布预留不足），再注意力kernel翻转计算受限（2bit组占比越过拐点），最后淘汰重排引发尾延迟抖动。通信碎片化与功耗墙在这三者之后才显现，因为NVL72域内带宽与功耗余量相对宽裕。这个次序决定了容量规划的抓手：池上限按bit分布的上界预留、kernel按2bit组占比分档、淘汰做成惰性批量，三者共同决定单节点可支撑的时长与batch组合。</p>\n<p>工程判断落在重要性打分的阈值上：阈值决定4bit帧占比，进而决定池上限、kernel受限程度与淘汰频率，是唯一同时牵动显存、计算与尾延迟的旋钮。把它当作容量规划的一等参数来标定，而不是当作量化精度的一个附属超参，是这类系统在Blackwell上跑稳的前提。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-38\">三十八 · 当压缩比撞上指令开销：2bit KV 池的崩点在哪</h3>\n<p>这套方案的显存账很好算，但真正的边界不在容量，而在注意力 kernel 的性质是否被改写。压缩后单帧 KV 占用按 <span class=\"formula\">$$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\ b_f\\in\\{2,4,8\\}$$</span> 逐帧累加，历史帧取 2bit、近期 4 帧留 FP8，池子总量被压到 FP8 的四分之一以下，192GB HBM 上可容纳的帧数与并发 batch 同时抬升。问题在于：压缩省下的是 HBM 带宽与容量，付出的却是 SM 内的指令周期。2bit 组读出要先按 bit 宽度分组 gather，再走 LUT 去量化、乘 per-group scale、叠加由相邻 FP8 帧插值得到的残差补偿项，每一步都在 tensor core 之外消耗发射与寄存器带宽。当 2bit 组占比升高，注意力从“等 HBM”变成“等指令”，roofline 拐点提前到来——此时增加帧数不再线性提升吞吐，反而因每 token 的注意力工作量变重而拉长单步时延。</p>\n<p>把这件事写成可判定的判据，比定性描述更有用。设历史帧中 2bit 组比例为 <span class=\"formula\">$$\\rho$$</span>，单次注意力读出的有效字节数为 <span class=\"formula\">$$B(\\rho)=N_h d\\left[(1-\\rho)\\cdot 1+\\rho\\cdot\\tfrac{1}{4}\\right]$$</span>（以 FP8 字节为 1），而指令开销近似为 <span class=\"formula\">$$C(\\rho)=c_0+\\rho\\,c_q$$</span>，其中 <span class=\"formula\">$$c_q$$</span> 是每组去量化加残差补偿的周期成本。带宽受限区要求 <span class=\"formula\">$$B(\\rho)/\\text{BW} &gt; C(\\rho)/\\text{IPC}$$</span>；随 <span class=\"formula\">$$\\rho$$</span> 上升，左侧线性下降、右侧线性上升，交点即为该 kernel 的压缩收益归零点。工程含义很直接：<span class=\"formula\">$$\\rho$$</span> 不是越高越好，超过交点后继续压历史帧只会让长序列吞吐不升反降，而画面质量还因 2bit 组过多出现注意力塌缩。这也是为什么分层 bit 宽度必须由重要性分数（注意力质量 + 帧间运动）来定，而不是一刀切全 2bit。</p>\n<table class=\"mini\"><thead><tr><th>规模抬升的维度</th><th>先崩的位置</th><th>系统代价表现</th></tr></thead><tbody><tr><td>时长（帧数）</td><td>注意力 kernel 指令开销</td><td>单步时延拉长，持续吞吐饱和甚至回落</td></tr><tr><td>并发 batch</td><td>KV 池上限与帧级淘汰</td><td>淘汰误删关键帧，场景跳变，尾延迟尖峰</td></tr><tr><td>序列长度跨节点</td><td>压缩池的 gather 与通信</td><td>按 bit 宽度分组的跨卡聚合放大 NCCL 消息数</td></tr></tbody></table>\n<p>规模上去后最先崩的往往不是显存，而是尾延迟。KV 池按帧/头分组存储、以帧级重要性淘汰控制上限，这套策略在稳态下平滑，但一旦请求时长分布出现长尾，淘汰逻辑会在解码中途触发：最旧低分帧被逐出，新帧注意力失去远端锚点，长程一致性下降并表现为场景跳变；同时被逐出帧对应的压缩块需要重排或回收，造成一次性的显存整理与 kernel 重配置，直接反映为 P99 首帧时延与持续吞吐的抖动。跨节点时更明显——2bit 组与 FP8 组混排意味着聚合通信的消息粒度不一致，按 bit 宽度分组 gather 会把一次大传输拆成多段小消息，NVLink 5 的带宽优势被消息数吃掉。因此容量规划不能只看“192GB 能装多少帧”，而要把 <span class=\"formula\">$$\\rho$$</span>、淘汰触发率与跨卡分组粒度一起纳入 SLO 预算；短序列或 batch 很小时，去量化开销压不过压缩收益，这套方案本就不该启用。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-39\">三十九 · 压缩比翻过临界点之后，先崩的是注意力 kernel 的指令流</h3>\n<p>把 KV 池从 FP8 压到 2bit/4bit 混合，显存账面上的收益是线性的：$\\mathrm{KV}_{\\text{mem}}\\approx \\sum_f b_f N_h d$，$b_f\\in\\{2,4,8\\}$。192GB HBM 上，历史帧占比越高、$b_f=2$ 的帧越多，池子能容纳的帧数与 batch 乘积就越大。但这条曲线在系统层面并不单调——每 token 注意力读出的字节数下降，而每字节要执行的指令数上升。2bit 组读出走的是分组 gather + 查表去量化 + per-group scale 乘加，再叠加相邻 FP8 帧插值残差 $\\gamma(K^{\\text{FP8}}_{f-1}+K^{\\text{FP8}}_{f+1})/2$，一个 2bit 元素在 kernel 里的有效操作数远高于一次 FP8 的 ldmatrix 直读。当 2bit 组占比越过某条线，注意力从带宽受限翻转为计算受限，长序列吞吐不升反降——这是该方案最先崩的地方，且崩在 SM 的 issue 槽而不是 HBM 控制器上。</p>\n<p>第二处先崩的是尾延迟而非均值。分层 bit 宽度意味着同一个注意力 kernel 内并存三条 gather 路径（2bit、4bit、FP8），warp 内分支发散随 2bit 组占比上升而加剧；近期窗口固定保留最近 4 帧 FP8，使每个 decode step 的 kernel 形状随帧序号周期性变化，尾帧（刚滑出 FP8 窗口、残差补偿项最多）的单步时延明显高于稳态帧。在线长视频请求的 SLO 以首帧时延与持续吞吐为主，尾延迟抬升会直接吃掉 batch 上调带来的吞吐余量。可用一张粗略的代价对照表定位瓶颈：</p>\n<table class=\"mini\"><thead><tr><th>瓶颈</th><th>触发条件</th><th>系统表现</th></tr></thead><tbody><tr><td>注意力指令开销</td><td>2bit 组占比高、残差补偿项多</td><td>kernel 转计算受限，吞吐不升反降</td></tr><tr><td>KV 池上限</td><td>帧级淘汰误删高分帧</td><td>batch×时长触顶，场景跳变</td></tr><tr><td>打分开销</td><td>每帧每头统计 amax 与注意力质量</td><td>与生成步串行，抬高首帧时延</td></tr></tbody></table>\n<p>第三处是重要性打分与淘汰策略本身的计算代价。每生成一帧都要按头/通道分组统计 amax 与注意力质量分数，这一步与自回归生成串行，无法完全藏进注意力 kernel 的流水里；帧级淘汰还要维护跨帧的重要性序，超长序列下这部分元数据虽小但访问模式散。更关键的是失效条件：打分分布若与自回归训练分布不匹配，高分帧被误判为低分而降 bit 或淘汰，长程一致性下降、出现场景跳变；反之 2bit 组占比过高则注意力塌缩，画面失去时空结构。工程判断是——该方案的规模上限由 KV 池上限与注意力 kernel 计算开销共同决定，短序列或 batch 很小时压缩收益不足以抵消去量化开销，应退回 FP8 路径；只有在历史帧占比高、近期帧需高精度的长视频自回归里，分层 bit 宽度才划算。</p>\n<h3 id=\"alg-2bit-kv-long-video-sec-40\">四十 · 精度失败模式：从“注意力塌缩”到“残差补偿失效”</h3>\n<p>在长视频自回归2bit KV量化里，精度失败很少表现为单帧明显崩坏，而是以“注意力分布变平—时空结构松动—场景跳变”的链条出现。根因在于2bit组的量化误差不再被近期FP8帧的残差补偿项完全吸收。读出公式为 <span class=\"formula\">$$\\hat{x}=q\\cdot s+r$$</span>，其中 $r$ 由相邻FP8帧插值得到；当历史帧与近期帧的运动差异大、插值方向与真实轨迹不一致时，$r$ 本身带偏，2bit组的去量化值就会系统性偏离。此时注意力质量分数高的头仍被保留在2bit组，注意力权重被压平，出现“注意力塌缩”：模型对远距离帧的区分度下降，画面失去时空结构。</p>\n<p>诊断这类问题不能只看整段PSNR。工程上应在注意力kernel内按头/帧分组埋点，统计每个2bit组的去量化残差范数与注意力熵：残差范数突然抬升、注意力熵向均匀分布靠拢，就是塌缩前兆。具体机制是把每层每头的注意力输出与FP8参考路径做逐帧余弦相似度抽样，抽样率按帧重要性分数反比设置，高分帧全采、低分帧稀疏采，避免监控本身把注意力kernel拖成计算受限。代价是监控采样占用注意力kernel约几个百分点的指令槽，换来的是能在场景跳变发生前若干帧触发回滚。</p>\n<p>例子：一个运动剧烈的镜头里，相邻FP8帧插值残差方向与真实运动相反，2bit组的历史帧KV被错误去量化，注意力权重摊平到所有历史帧，生成画面出现背景纹理重复。此时把该帧对应头的bit宽度从2bit提升到4bit、并暂停对该帧的残差补偿插值，即可在下一帧恢复结构。判断依据是注意力熵与残差范数的联合阈值，而非单一指标。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-41\">四十一 · 显存与OOM：KV池上限、帧级淘汰与碎片</h3>\n<p>OOM在Blackwell 192GB HBM档位上通常不是“总量不够”，而是KV池按帧/头分组存储后的碎片与峰值叠加。KV显存近似为 <span class=\"formula\">$$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\ b_f\\in\\{2,4,8\\}$$</span>，其中 $b_f$ 是该帧每头的bit宽度。分层bit宽度让 $b_f$ 随帧重要性变化，池内出现2bit、4bit、FP8三种尺寸的块，分配器若按最大块对齐就会浪费；更隐蔽的是淘汰策略误删关键帧后，为维持长程一致性而重新保留该帧的KV，造成池上限被瞬时突破。</p>\n<p>机制上应把KV池做成按帧索引的变长块表，2bit组以查表去量化的固定粒度（按通道分组）分配，FP8近期窗口单独占一块连续区域，避免与历史帧混排。淘汰按帧级重要性分数执行，但保留一个“不可淘汰”的近期窗口（最近4帧）与一个“观察期”缓冲：被淘汰帧先降级到2bit并留在观察期若干帧，若其注意力质量分数回升则恢复，否则真正释放。这样把误删关键帧的场景跳变转成可逆的降级。</p>\n<p>系统代价：观察期缓冲等于把KV池上限抬高一个比例，直接压缩batch与时长；但相比OOM后整批失败重跑，这个预留是划算的。监控应盯三个量：池占用率、变长块碎片率、淘汰后恢复率。碎片率持续上升说明分配粒度与bit宽度分布不匹配，需要调分组大小；恢复率高说明重要性打分对运动帧过于敏感，应把帧间运动项权重下调。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-42\">四十二 · 批抖动与路由不均：连续批处理下的2bit组倾斜</h3>\n<p>批抖动来自请求间的bit宽度分布不一致。一个长视频请求的历史帧多、2bit组占比高，其注意力kernel走查表去量化路径，指令开销大；一个短请求近期帧多、FP8组占比高，走带宽路径。连续批处理把两者拼进同一批时，kernel按最慢路径编译，短请求被长请求的2bit组拖慢，表现为批内尾延迟尖刺。路由不均则是另一面：调度器若按请求数而非按2bit组字节数分配SM，会出现某些SM全在跑2bit去量化、另一些SM在等FP8 gather，SM间负载倾斜。</p>\n<p>诊断机制是在调度层维护每个请求的“2bit组占比”与“预计注意力指令数”两个标签，批组装时按这两个标签做分桶，而不是简单按到达顺序。伪代码思路：对每个候选批计算 <span class=\"formula\">$$\\text{cost}(B)=\\max_{r\\in B}\\big(\\alpha\\cdot \\text{bytes}_{2\\text{bit}}(r)+\\beta\\cdot \\text{bytes}_{\\text{FP8}}(r)\\big)$$</span>，以最小化批内最大代价为目标做贪心装箱，同时约束批内2bit组占比方差。代价是调度器多一次排序，换来尾延迟尖刺收敛。</p>\n<p>例子：在线服务里一个32帧长请求与若干4帧短请求同批，长请求的2bit组使kernel从带宽受限转为计算受限，短请求的首帧时延被拉长。按2bit组占比分桶后，长请求单独成批、短请求成批，两类批各自走最适合的kernel变体，持续吞吐与首帧时延同时改善。监控指标是批内2bit组占比的分布宽度与P99批时延，宽度大就说明分桶粒度不够细。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-43\">四十三 · 尾延迟尖刺：淘汰、重算与去量化路径切换</h3>\n<p>尾延迟尖刺有三个典型来源。其一是帧级淘汰触发的重算：淘汰最旧低分帧后，若后续注意力需要该帧信息，模型只能靠残差补偿项近似，近似失败则触发回退到更高bit宽度重算该帧KV，重算本身是一次前向，尖刺明显。其二是去量化路径切换：同一请求内2bit组与FP8组比例跨过阈值时，kernel从查表路径切到gather路径，切换瞬间的流水线气泡表现为尖刺。其三是重要性打分与自回归训练分布不匹配，打分抖动导致bit宽度频繁升降，每次升降都要重写KV池块。</p>\n<p>机制上应对淘汰做“延迟释放+预取补偿”：淘汰帧的2bit块不立即释放，而是标记为可覆盖，同时预计算其残差补偿项缓存；若后续需要，直接用缓存补偿而不重算。对路径切换，把kernel变体选择从按请求改为按批内主导路径，并给切换加滞回窗口，避免比例在阈值附近抖动。对打分抖动，给bit宽度升降加最小驻留帧数，升降只在连续若干帧同向时才执行。</p>\n<p>系统代价：预取补偿缓存占用额外显存，滞回窗口让部分帧多停留在较高bit宽度，两者都压缩KV池上限。监控应记录尖刺与淘汰事件、路径切换事件的时间相关性，若尖刺集中在淘汰后若干帧，说明补偿缓存命中率不足，应扩大缓存或降低淘汰激进程度。例子：超长序列在淘汰一批低分帧后连续出现尾延迟尖刺，把淘汰批量从逐帧改为按窗口批量、并预取补偿项后，尖刺幅度收敛到与常规批时延同量级。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-44\">四十四 · 监控体系与回滚：从指标到可执行动作</h3>\n<p>监控要覆盖三层：精度层（注意力熵、残差范数、逐帧余弦相似度抽样）、资源层（KV池占用、碎片率、2bit组占比、SM负载方差）、时延层（首帧时延、P99批时延、尖刺频率）。三层指标必须带帧级与头级标签，否则无法定位是哪个2bit组出问题。机制上把指标采集做成注意力kernel内的轻量旁路，按重要性分数反比采样，高分帧全采、低分帧稀疏采，采集开销随2bit组占比上升而下降，避免监控本身把kernel推向计算受限。</p>\n<p>回滚不是“整请求回退到FP8”，而是分级动作：一级是把问题头的bit宽度从2bit升到4bit并暂停该头残差补偿；二级是把该帧移出2bit组、临时保留FP8；三级是整请求回退到统一FP8 KV并重置淘汰策略。分级依据是精度层指标的越界幅度与持续帧数。回滚动作要写进KV池块表，保证后续帧的gather按新bit宽度执行，避免读写不一致。</p>\n<p>工程判断：回滚的触发阈值应与SLO绑定，首帧时延敏感的场景容忍更高bit宽度、更低压缩率，持续吞吐敏感的场景容忍精度层指标更宽的回滚窗口。例子：一个长视频在线请求在运动剧烈段触发一级回滚，问题头升到4bit后注意力熵恢复，未触发二级；若同一段连续多帧越界，则升级到二级并把该帧移出2bit组，代价是该请求KV池占用上升、批内可容纳请求数下降，调度器需同步调低该请求的并发权重。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-45\">四十五 · 失败模式与训练分布的耦合：淘汰策略的边界</h3>\n<p>重要性打分融合注意力质量与帧间运动，这个打分函数若与自回归训练分布不匹配，会出现两类系统性失败：一是运动剧烈的帧被过度保留FP8，2bit组占比过低，压缩收益不足以抵消去量化开销，长序列吞吐不升反降；二是静态长镜头被过早降到2bit并淘汰，长程一致性下降，出现场景跳变。诊断方法是把打分分布与训练时的帧重要性分布做对比，若在线打分的高分帧集中在运动帧、而训练分布里静态关键帧也占高分，说明运动项权重过大。</p>\n<p>机制上给打分加一个分布校准项：用近期若干帧的打分均值与方差做在线归一化，使bit宽度分配对场景类型不敏感；同时对淘汰加“关键帧保护”，把注意力质量分数进入前若干分位的帧标记为不可淘汰，即便其运动项低。代价是保护帧占用池上限，压缩batch；但相比场景跳变导致的整段重生成，这个代价可控。</p>\n<p>例子：一个以静态背景为主、少量物体运动的长视频，在线打分把运动帧全保留FP8、静态关键帧降到2bit并淘汰，后续镜头切换时背景结构丢失。加入分布校准与关键帧保护后，静态关键帧保留在4bit、运动帧按需保留FP8，2bit组占比回到合理区间，注意力熵稳定。监控应记录保护帧占比与2bit组占比的联合分布，两者同时偏离设计配方就是打分失配的信号。</p>\n<p>最终落在具体机制上：把bit宽度分配、淘汰、回滚三件事统一到一张按帧/头索引的状态表里，每次读写都带bit宽度与残差补偿版本号，任何回滚只改状态表而不改已写入的块，保证gather路径与写入路径的一致性。这张状态表就是诊断与回滚的执行面，指标越界时改的是表项，不是重跑整个请求。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-46\">四十六 · 失效边界：当2bit压缩把注意力kernel推向计算受限</h3>\n<p>这套方案的系统代价有一个明确的翻转点：注意力kernel原本在Blackwell上受HBM带宽约束，2bit组查表去量化、per-group scale乘加与相邻FP8帧插值残差补偿三项指令叠加后，算术强度上升，kernel可能转为计算受限。此时KV池虽然缩小、batch可以放大，但单帧注意力时延被指令开销吃掉，长序列吞吐不升反降。诊断信号是注意力kernel的SM占用率与issue stall比例同时抬升、而HBM读取量下降——一旦出现这种“带宽降、算力涨”的反向剪刀差，就应下调2bit组占比或缩短残差补偿的插值范围。量化本身的误差界由<div class=\"formula\">$$|x-\\hat{x}|\\le \\frac{s}{2}+|r|,\\quad s=\\frac{\\mathrm{amax}}{2^{b-1}}$$</div>给出，per-group粒度越细、$s$越小，但组数增多会放大gather与scale读取的指令数，这是精度与kernel开销之间的直接兑换。</p>\n<p>第二类失效来自打分与淘汰策略和自回归训练分布不匹配。重要性分数融合注意力质量与帧间运动，若训练时的注意力模式与在线推理的实际分布漂移，高分头/帧的判定就会错位：该保留FP8的剧烈运动帧被降为2bit，或帧级淘汰误删了后续被反复attend的关键帧，表现为长程一致性下降与场景跳变。工程上应把打分分布做成可观测量——按帧记录被淘汰帧在后续窗口内的累计注意力质量，若该值超过保留阈值即触发回滚到纯FP8近期窗口加保守淘汰。全2bit或2bit组占比过高还会引发注意力塌缩，画面失去时空结构，这是最不可逆的失效，必须在灰度阶段用2bit组占比上限硬约束。</p>\n<p>监控与回滚按三层组织：精度层跟踪去量化残差$|r|$的分布与2bit组注意力熵，熵骤降即塌缩前兆；显存层跟踪KV池按帧/头分组的占用与淘汰速率，逼近池上限时提前扩容而非被动OOM；时延层跟踪首帧时延与尾延迟尖刺，区分是gather不均衡（部分头2bit组集中导致路由不均）还是批抖动。回滚路径保持分级：先关残差补偿降指令开销，再把历史帧整体抬到4bit，最后退回FP8近期窗口加帧级淘汰的保守配置；每级都对应可测量的吞吐与一致性代价，避免一次性全量回退浪费已压缩的显存收益。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>kernel转计算受限</td><td>HBM读取降、SM占用与stall升</td><td>降2bit组占比、缩插值范围</td></tr><tr><td>注意力塌缩</td><td>2bit组注意力熵骤降</td><td>硬限2bit占比、抬4bit</td></tr><tr><td>场景跳变</td><td>淘汰帧后续注意力质量超阈值</td><td>保守淘汰、近期窗口回FP8</td></tr></tbody></table>\n<h3 id=\"alg-2bit-kv-long-video-sec-47\">四十七 · 对照轴：压缩率、精度分层与 kernel 形态</h3>\n<p>把相邻算法放在同一张坐标纸上，先要确定比较轴。长视频自回归推理的 KV 压缩方案，差异不在“压不压”，而在三件事上分叉：历史帧被压到多窄、近期帧是否保留宽位宽、以及去量化发生在 kernel 的哪个阶段。FP8 KV 是基线：历史帧与近期帧同精度，读出无需查表，注意力仍是带宽受限的流式 gather。统一低 bit 量化（全 2bit 或全 4bit）把压缩率推到极限，但近期帧也一起损失，注意力分布容易塌缩。本算法走的是分层路线：近期窗口（最近 4 帧）留 FP8，历史帧按重要性落到 2bit 或 4bit，读出时 2bit 组查表去量化并叠加相邻 FP8 帧插值残差。三条路线的 kernel 形态因此不同——FP8 是纯带宽问题，统一低 bit 是带宽加一次固定查表，分层则是按 bit 宽度分支的 gather 加插值补偿，指令路径最长。</p>\n<p>用公式把分叉点写清楚：</p>\n<div class=\"formula\">$$\\hat{K}_{f}=s_f\\cdot \\mathrm{LUT}(K^{2\\text{bit}}_{f})+\\gamma\\,(K^{\\text{FP8}}_{f-1}+K^{\\text{FP8}}_{f+1})/2,\\quad \\text{KV}_{\\text{mem}}\\approx \\sum_f b_f\\,N_h d,\\ b_f\\in\\{2,4,8\\}$$</div>\n<p>第二项只在存在相邻 FP8 帧时非零，这意味着分层方案的有效性依赖“近期窗口与历史帧交错”的帧序结构；若淘汰策略把 FP8 帧清空，残差补偿项退化为零，2bit 组就回到裸量化。工程判断的第一条由此而来：分层量化的收益不是压缩率本身，而是压缩率与残差锚点共存。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-48\">四十八 · 决策表：五种工况下的选型</h3>\n<p>下表把可用事实中的边界条件落成可执行的选型规则。表中“收益”指 KV 显存与可支撑时长/batch，“代价”指注意力 kernel 侧的指令开销与一致性风险。</p>\n<table class=\"mini\"><thead><tr><th>工况</th><th>首选</th><th>次选</th><th>不适用</th><th>判据</th></tr></thead><tbody>\n<tr><td>历史帧占比高、近期帧需高精度</td><td>本算法（2/4/8bit 分层）</td><td>FP8 KV</td><td>统一低 bit</td><td>残差锚点存在，注意力不塌缩</td></tr>\n<tr><td>短序列、batch 很小</td><td>FP8 KV</td><td>—</td><td>本算法</td><td>去量化开销压过显存收益</td></tr>\n<tr><td>显存极紧、时长优先于画质</td><td>统一 2bit</td><td>本算法降 4bit 占比</td><td>FP8 KV</td><td>192GB 池上限先撞墙</td></tr>\n<tr><td>注意力已计算受限</td><td>FP8 KV 或稀疏注意力</td><td>本算法仅压历史帧</td><td>全 2bit</td><td>kernel 从带宽受限转计算受限</td></tr>\n<tr><td>训练分布与打分器不匹配</td><td>FP8 KV 保守档</td><td>本算法加淘汰保护</td><td>激进淘汰</td><td>场景跳变风险</td></tr>\n</tbody></table>\n<p>读表的关键是第二行与第四行。短序列时 KV 池远未触及 192GB 上限，2bit 去量化与残差插值的指令开销纯属净损失；注意力已计算受限时，再叠加查表分支只会让长序列吞吐不升反降——这正是失败模式里“从带宽受限转为计算受限”的具体形态。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-49\">四十九 · 与 FP8 KV 的边界：收益何时为正</h3>\n<p>设历史帧数为 $F_h$、近期窗口为 $F_r$（取 4），每帧每头维度为 $N_h d$。FP8 下 KV 池近似正比于 $(F_h+F_r)\\cdot 8$，分层下近似 $F_h\\cdot \\bar{b}+F_r\\cdot 8$，$\\bar{b}$ 为历史帧平均位宽。当 $\\bar{b}$ 落在 2 到 4 之间，压缩比大致在 1.6 到 4 倍区间，这正是“压到 FP8 的 1/4 以下”的来源。但收益要扣掉 kernel 侧代价：2bit 组每元素多一次查表与一次 scale 乘，残差项再多一次插值加。带宽节省是线性的，指令开销随 2bit 组占比线性上升，两者在某个占比处交叉。交叉点由 GPU 的查表吞吐与 HBM 带宽之比决定，工程上应把它当作可测量的拐点而非先验常数：在目标 batch 与帧长下扫 2bit 组占比，观察注意力 kernel 的实际耗时曲线是否出现上翘。</p>\n<p>具体例子：单节点 NVL72 上跑长视频自回归在线服务，batch 受 KV 池上限约束，SLO 以首帧时延与持续吞吐为主。若把历史帧全压 2bit，池上限放宽、batch 变大，但注意力 kernel 每步多出的查表与插值在长序列上累积，持续吞吐可能低于 FP8 档；把历史帧改为 2bit/4bit 混合、只对注意力质量低的头降 2bit，则 2bit 组占比下降、指令开销回落，同时池上限仍显著优于 FP8。这就是分层而非全压的工程理由。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-50\">五十 · 与统一低 bit 量化的边界：残差锚点的作用</h3>\n<p>统一低 bit 与本算法的差别不在量化公式，而在读出路径是否带锚点。统一 2bit 的读出是 $\\hat{x}=q\\cdot s$，误差只由 per-group scale 承担；本算法在 2bit 组上叠加 $\\gamma\\,(K^{\\text{FP8}}_{f-1}+K^{\\text{FP8}}_{f+1})/2$，用相邻 FP8 帧的插值把帧间运动方向上的系统性偏差拉回。视频 KV 的误差不是各向同性的：帧间运动剧烈的区域，2bit 的组内动态范围被压缩得最狠，裸量化会把注意力质量从正确帧头转移到邻近帧头，表现为注意力塌缩、画面失去时空结构。插值残差补偿恰好作用在这个方向上，代价是要求相邻帧保持 FP8。</p>\n<p>由此得到适用条件：只有当近期窗口与历史帧在时间上交错、且淘汰策略不把 FP8 帧清空时，残差项才有定义。若为了压池上限把 FP8 窗口也降位，残差锚点消失，本算法退化为统一低 bit 加额外指令开销，是最差组合。工程上应把“FP8 帧数量下限”作为淘汰器的硬约束，而不是让帧级重要性打分自由决定。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-51\">五十一 · 与稀疏注意力、投机解码的叠加关系</h3>\n<p>相邻条目里的动态稀疏时空注意力解决的是“算哪些 token”，本算法解决的是“存多宽”。两者正交但相互影响：稀疏注意力跳过大量历史 token 后，2bit 组的 gather 次数下降，去量化开销随之下降，分层量化的交叉点右移，收益变正；反过来，若稀疏模式恰好集中在高重要性头，而这些头又被保留为 4bit/FP8，则压缩收益被稀疏性抵消一部分。选型时应先定稀疏度再定 bit 分层，而不是反过来。</p>\n<p>与视频自回归投机解码的叠加则是资源竞争关系。投机解码用额外 draft 前向换接受率，其收益依赖单步解码延迟；分层量化把注意力推向计算受限后，单步延迟上升，投机解码的性价比下降。因此在同一服务里同时开两者时，应把 2bit 组占比压到交叉点以下，把省下的带宽留给 draft 模型的 KV，而不是把历史帧压到极限。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-52\">五十二 · 打分器与淘汰器的选型判据</h3>\n<p>重要性打分融合注意力质量与帧间运动，这两项都依赖对自回归训练分布的假设。若打分器与训练分布不匹配，高运动帧被误判为低重要性而降 2bit，长程一致性下降并出现场景跳变——这是失败模式里最难在线诊断的一类，因为单帧画质正常、跨帧结构才崩。选型判据是：打分器必须在目标模型的真实自回归 rollout 上校准，而不是在短片段上拟合；校准指标用跨帧注意力的一致性而非单帧重建误差。</p>\n<p>淘汰器的判据更硬：帧级重要性淘汰控制 KV 池上限，但误删关键帧造成的跳变不可逆。工程做法是给淘汰加滞后与保护带——最旧低分帧先降位宽再淘汰，FP8 帧数量设下限，关键帧（高注意力质量且高运动）进入保护集不参与淘汰。这样池上限由保护集大小与位宽分布共同决定，而不是由打分器的瞬时输出决定。最终判断落在一条可执行的规则上：先按稀疏度定注意力形态，再按 2bit 组占比定分层档位，最后用保护集约束淘汰器；三者中任一越界，退回 FP8 KV 保守档，用显存换一致性。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-53\">五十三 · 分层低比特 KV 的选型边界与失效条件</h3>\n<p>把本方案放进同族算法的坐标系里，它的位置由两个正交维度决定：历史帧的比特宽度是否分层，以及读出时是否做跨帧残差补偿。FP8 KV 在两个维度上都取“否”，因此显存占用随帧数线性上升，在 192GB HBM 上很快把 batch 与时长同时压死；统一低比特量化在第一个维度上取“是”但取的是均一值，全 2bit 会让注意力分布塌缩、画面失去时空结构；本方案在两个维度上都取“是”，近期 4 帧保留 FP8、历史帧按重要性降到 2bit 或 4bit，并用相邻 FP8 帧插值出残差项补回 2bit 组的系统性偏差。选型的判据不是“谁压得更狠”，而是历史帧在总 KV 中的占比：占比高、且近期帧精度对时空一致性不可让步时，分层方案才有净收益；短序列或 batch 很小时，压缩省下的显存换不回查表去量化与残差补偿的指令开销，直接上 FP8 更划算。</p>\n<p>决策表按三个可观测输入给出分流，避免凭直觉选型：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>历史帧占比</th><th>注意力 kernel 余量</th><th>选型</th></tr></thead><tbody><tr><td>短序列、batch 小</td><td>低</td><td>充裕</td><td>FP8 KV，不引入去量化路径</td></tr><tr><td>长程一致性要求硬、运动剧烈</td><td>高</td><td>充裕</td><td>本方案，近期 4 帧 FP8 + 历史 2/4bit 分层</td></tr><tr><td>显存极紧、可容忍结构退化</td><td>高</td><td>紧张</td><td>统一低比特，接受注意力塌缩风险</td></tr><tr><td>历史帧占比中等、SLO 偏首帧时延</td><td>中</td><td>紧张</td><td>本方案但收紧 2bit 组占比，或退回 FP8</td></tr></tbody></table>\n<p>系统代价的转折点可以写成一个粗略的判据。设压缩前每帧每头 KV 的字节数为 $b_{\\text{FP8}}N_hd$，分层后为 $\\sum_f b_fN_hd$，$b_f\\in\\{2,4,8\\}$；显存收益是线性的，但注意力读出的指令开销随 2bit 组占比上升而非线性上升——查表去量化、per-group scale 乘法、残差插值三项都要在 kernel 内逐组完成。当 2bit 组占比越过某条界线，注意力从带宽受限翻转为计算受限，长序列吞吐不升反降，这正是本方案最典型的失败模式。工程上应把 2bit 组占比当作一个可调旋钮而非固定策略，按帧级重要性分数动态收紧，而不是一次性把历史帧全部压到 2bit。</p>\n<p>失效条件集中在两处。其一是重要性打分与自回归训练分布不匹配：打分融合注意力质量与帧间运动，若训练时的帧间运动统计与实际在线请求的分布漂移，高分帧会被误判为低分而压到 2bit，长程一致性下降；帧级淘汰误删关键帧则直接表现为场景跳变。其二是全 2bit 或 2bit 组占比过高导致注意力塌缩，此时残差补偿只能补回均值偏差，补不回被量化抹掉的通道间相对结构。因此近期窗口的 FP8 锚点、插值残差、帧级淘汰三者必须同时在场，缺一项都会把边界推向失效侧。规模上限由 KV 池上限与注意力 kernel 计算开销共同封顶：前者决定能存多长，后者决定读得多快，二者取小。</p>\n\n<h3 id=\"alg-2bit-kv-long-video-sec-54\">五十四 · 选型边界：什么条件下该用分层2bit，而不是FP8或统一低bit</h3>\n<p>把这条方案放进同族算法谱系里，决策变量其实只有三个：历史帧在KV池中的占比、注意力kernel当前是带宽受限还是计算受限、以及重要性打分能否与训练分布对齐。与纯FP8 KV相比，它用<em>帧级分层</em>换取容量——近期4帧留FP8、历史帧按分数降到2bit/4bit，KV显存按帧求和$\\text{KV}_{\\text{mem}}\\approx \\sum_f b_f N_h d,\\ b_f\\in\\{2,4,8\\}$，只有当历史帧数量远大于近期窗口时，这个求和才真正被$b_f=2$的项主导，压缩收益才成立。与统一低bit量化相比，它的代价不在显存而在kernel：读出时2bit组要查表去量化、再加插值残差$\\gamma(K^{\\text{FP8}}_{f-1}+K^{\\text{FP8}}_{f+1})/2$，指令数随2bit组占比线性上升。因此选型的第一个判据是<strong>历史帧占比</strong>：短序列或batch很小时，历史帧本就少，压缩省下的HBM换不回多出来的去量化周期，直接留在FP8更稳。</p>\n<p>第二个判据是<strong>注意力kernel的受限类型</strong>。FP8 KV下注意力通常贴着HBM带宽跑，算力有余；一旦大量头/帧落到2bit组，每字节要付出查表与残差补偿的指令开销，算术强度上移，kernel可能翻转为计算受限——此时长序列吞吐不升反降。工程上应把2bit组占比当作一个可调阀门：先按重要性分数排序，只把分数最低、且注意力质量贡献可忽略的历史帧压到2bit，保留4bit作为中间档，使去量化开销落在SM闲置周期里。判断是否翻转的粗略信号是注意力阶段的issue slot利用率与HBM吞吐的同时走势，二者一升一降即说明已越过拐点。</p>\n<p>第三个判据是<strong>打分与淘汰策略是否与自回归训练分布匹配</strong>。重要性分数融合注意力质量与帧间运动，运动剧烈的帧倾向留FP8以避免注意力塌缩；但若训练时的帧间相关性分布与在线打分假设不一致，低分帧被误淘汰会造成场景跳变，而全2bit或2bit组占比过高则直接让画面失去时空结构。这条失效条件无法靠调参消除，只能靠保守策略兜底：近期窗口固定FP8、残差补偿始终开启、帧级淘汰设下限而非无限压缩。</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>首选</th><th>理由</th></tr></thead><tbody><tr><td>历史帧占比高、近期帧需高精度</td><td>分层2bit/4bit+FP8窗口</td><td>容量收益由历史帧主导，近期精度不塌</td></tr><tr><td>序列短或batch小</td><td>FP8 KV</td><td>去量化开销无法被容量收益抵消</td></tr><tr><td>注意力已计算受限</td><td>FP8或4bit为主</td><td>2bit查表进一步推高指令开销</td></tr><tr><td>打分分布与训练不匹配</td><td>统一低bit+保守淘汰</td><td>避免误删关键帧引发跳变</td></tr></tbody></table>\n<p>落到Blackwell 192GB HBM档位，这条方案的规模上限由KV池上限与注意力kernel计算开销共同决定，而非单纯由显存决定：池上限管住能保留多少帧，kernel开销管住每帧读出多快。部署时把2bit组查表去量化放进注意力kernel内完成、按bit宽度分组gather，是为了避免额外的解压pass把带宽优势吃掉；一旦发现吞吐被指令开销锁死，正确动作是回退部分头到4bit或FP8，而不是继续加大压缩率。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 少步蒸馏与轨迹缓存复用</td></tr><tr><td>解决什么</td><td>自回归视频生成把历史帧的KV cache持续保留以维持长程一致性，KV随帧数线性增长，在Blackwell 192GB…</td></tr><tr><td>一句话机制</td><td>对历史帧KV按通道分组做2bit量化，保留近期帧为FP8/FP4混合精度，用重要性分数（注意力质量+帧间运动）决定每帧…</td></tr><tr><td>代价与失效</td><td>2bit去量化与残差补偿增加注意力kernel的指令开销，可能使注意力从带宽受限转为计算受限。；重要性打分与帧淘汰策略需与自回归训练分布匹…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-2bit-kv-long-video · 共 8 个片段</p>\n";break;}}})();
